sni/codes.py:
"""Codes (spec §2 ``code``; §4 step 1): dense prototypes or sparse expanded k-WTA codes (H-03)."""

from __future__ import annotations

import numpy as np


class Code:
    """``code ∈ {dense, sparse}``. Sparse: fixed seeded random expansion to D = expansion·d,
    then k-winners-take-all → a binary code scaled to unit norm (FlyHash-style). Dense: identity."""

    def __init__(self, kind: str, dim: int, *, expansion: int = 8, fraction: float = 0.05,
                 seed: int = 0) -> None:  # fmt: skip
        if kind not in ("dense", "sparse"):
            raise ValueError(f"code={kind!r}")
        self.kind, self.in_dim = kind, dim
        if kind == "sparse":
            rng = np.random.default_rng(np.random.SeedSequence([seed, 0xC0DE]))
            self.D = dim * int(expansion)
            self.k = max(1, int(round(fraction * self.D)))
            self.M = rng.normal(size=(self.D, dim))
            self.dim = self.D
        else:
            self.dim = dim

    def __call__(self, z: np.ndarray) -> np.ndarray:
        if self.kind == "dense":
            return np.asarray(z, dtype=float)
        h = self.M @ z
        out = np.zeros(self.D)
        out[np.argpartition(h, -self.k)[-self.k :]] = 1.0 / np.sqrt(self.k)  # unit norm
        return out

    def similarity(self, c: np.ndarray, stored: np.ndarray) -> np.ndarray:
        """Overlap of a code with stored codes in [−1, 1] (cosine; for binary k-WTA codes this
        is the fraction of shared active bits)."""
        if stored.shape[0] == 0:
            return np.zeros(0)
        num = stored @ c
        den = np.linalg.norm(stored, axis=1) * (np.linalg.norm(c) + 1e-12) + 1e-12
        return num / den

sni/consolidation.py:
"""Consolidation (spec §5; switch ``consolidation ∈ {write, offline, both, none}``).

* write-time (ART-style): a confirmed naming of input x merges into the winning prototype if it
  lies within vigilance *and* the winner already names the same word (match tracking); else a
  new provisional unit is formed. Decided by :func:`write_time_target`.
* offline pass (:func:`offline_pass`), gated by predictability: merge, split, downscale, prune.
  A merge needs the pooled exemplars to be predicted by the pair (``merge_predictability``); a
  split needs a contradicted unit whose exemplars form two modes novel to each other.
  Every change it makes to a learned quantity is a *replay* through the same audited update
  functions (L5: each replay update satisfies L1–L4): a merge replays the absorbed unit's stored
  exemplars into the survivor; a split replays one mode's exemplars into a new unit; downscaling
  is ``update_downscale``. Consolidated items are never pruned.

Episodic store: traces are never edited; the offline pass instead forms level-2 *concept*
prototypes by replaying the traces that share a confirmed name (episodic → concept prototypes).
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

import numpy as np

from sni.plasticity import update_downscale, update_edge_named, update_prototype_stats

if TYPE_CHECKING:  # pragma: no cover
    from sni.engine import Brain


def write_time_target(brain: Brain, code: np.ndarray, word_unit: int, relation: str) -> int:
    """The unit a confirmed naming merges into, or -1 for "form a new unit"."""
    cfg = brain.cfg
    if cfg.store != "prototype" or cfg.consolidation not in ("write", "both"):
        return -1
    m = brain.match_code(code)
    if m.profile.best < 0 or m.profile.eps0 > cfg.engine.vigilance:
        return -1
    best = m.profile.best
    if brain.answer_of(best, relation) not in (word_unit, -1):
        return -1  # match tracking: the winner names something else → new unit
    return best


def _named_answer(brain: Brain, unit: int) -> int:
    return brain.answer_of(unit, "named") if "named" in brain.edges.types else -1


def _replay_into(brain: Brain, target: int, codes: list[np.ndarray]) -> None:
    """Replay stored exemplars into ``target`` with the replay modulator m = +1 (the stored,
    already-confirmed verdict); each replay is one local prototype update."""
    eta = brain.cfg.params.eta_phi
    for x in codes:
        delta = update_prototype_stats(
            np.asarray(x), brain.units.theta_stats(target)[0], 1.0, eta=eta
        )
        brain.units.commit_stats(target, delta[None])


def offline_pass(brain: Brain) -> dict[str, Any]:
    cfg, p, units, edges = brain.cfg, brain.cfg.engine, brain.units, brain.edges
    stats = {"merged": 0, "split": 0, "concepts": 0, "downscaled": 0, "pruned_edges": 0,
             "pruned_units": 0}  # fmt: skip
    percepts = [int(i) for i in units.ids("percept")]

    if cfg.store == "prototype":
        # (a) gated merge of provisional pairs that name the same word
        for a in percepts:
            if not units.meta[a].alive or units.meta[a].consolidated:
                continue
            for b in percepts:
                if b <= a or not units.meta[b].alive or units.meta[b].consolidated:
                    continue
                wa, wb = _named_answer(brain, a), _named_answer(brain, b)
                if wa < 0 or wa != wb:
                    continue
                va, vb = units.var[a] + units.var_floor, units.var[b] + units.var_floor
                d2 = (units.phi[a] - units.phi[b]) ** 2
                if np.mean(d2 / va) > p.vigilance or np.mean(d2 / vb) > p.vigilance:
                    continue
                pool = units.meta[a].exemplars + units.meta[b].exemplars
                if not pool or _predictability(brain, pool, {a, b}) < p.merge_predictability:
                    continue  # unpredictable items stay separate (Go-CLS gate)
                _replay_into(brain, a, [np.asarray(x) for x in units.meta[b].exemplars])
                units.meta[a].exemplars = (units.meta[a].exemplars + units.meta[b].exemplars)[
                    : units.reservoir
                ]
                _kill_unit(brain, b)
                stats["merged"] += 1
        # split bimodal units (replay one mode into a new unit)
        for a in [int(i) for i in units.ids("percept")]:
            ex = units.meta[a].exemplars
            # gate: only a unit whose predictions were contradicted is a split candidate
            if units.meta[a].consolidated or units.meta[a].contra <= 0 or len(ex) < 4:
                continue
            X = np.asarray(ex)
            lab = _two_means(X)
            if lab is None:
                continue
            c0, c1 = X[lab == 0].mean(0), X[lab == 1].mean(0)
            if np.mean((c0 - c1) ** 2 / (units.var[a] + units.var_floor)) <= p.theta_novel:
                continue  # the two modes would not be novel to each other: no split
            word = _named_answer(brain, a)
            new = units.add("percept", X[lab == 1][0], t=brain.t)
            _replay_into(brain, new, list(X[lab == 1][1:]))
            units.meta[new].exemplars = [list(x) for x in X[lab == 1]]
            units.meta[a].exemplars = [list(x) for x in X[lab == 0]]
            if word >= 0:
                e = edges.add(new, "named", word, t=brain.t)
                edges.commit_w(
                    e, update_edge_named(1.0, True, eta=float(edges.w[edges.get(a, "named", word)]))
                )
            stats["split"] += 1
    elif cfg.store == "episodic" and "named" in edges.types:
        groups: dict[int, list[int]] = {}
        for a in percepts:
            w = _named_answer(brain, a)
            if w >= 0:
                groups.setdefault(w, []).append(a)
        have = {_named_answer(brain, c) for c in units.ids("concept")}
        for word, members in sorted(groups.items()):
            if word in have or len(members) < 2:
                continue
            codes = [units.phi[i] for i in members]
            sims = [
                float(np.dot(x, codes[0]) / (np.linalg.norm(x) * np.linalg.norm(codes[0]) + 1e-12))
                for x in codes[1:]
            ]
            if np.mean(sims) < 1.0 - p.vigilance / p.retrieval_beta:
                continue  # predictability gate: the traces do not cluster
            c = units.add("concept", codes[0], t=brain.t, level=2)
            _replay_into(brain, c, codes[1:])
            e = edges.add(c, "named", word, t=brain.t)
            edges.commit_w(e, update_edge_named(1.0, True, eta=brain.cfg.params.eta))
            stats["concepts"] += 1

    # (b) downscale provisional edges, (c) prune weak unsupported ones and weak units
    live = [int(i) for i in edges.live() if not edges.meta[i].consolidated]
    if live:
        edges.commit_w(live, update_downscale(edges.w[live], rho=p.downscale))
        stats["downscaled"] = len(live)
    for i in live:
        if edges.w[i] < p.prune_w and not any(v > 0 for v in edges.meta[i].support.values()):
            edges.kill(i)
            stats["pruned_edges"] += 1
    for a in [int(i) for i in units.ids("percept")] + [int(i) for i in units.ids("concept")]:
        m = units.meta[a]
        if not m.consolidated and units.s[a] < p.s_min:
            _kill_unit(brain, a)
            stats["pruned_units"] += 1
    return stats


def _kill_unit(brain: Brain, unit: int) -> None:
    brain.units.kill(unit)
    for r in brain.edges.types:
        for e in brain.edges.outgoing(unit, r):
            brain.edges.kill(e)


def _predictability(brain: Brain, pool: list[list[float]], members: set[int]) -> float:
    """Share of the pooled exemplars whose best-matching unit is one of ``members``."""
    hits = 0
    for x in pool:
        m = brain.match_code(np.asarray(x))
        hits += int(m.profile.best in members)
    return hits / len(pool)


def _two_means(X: np.ndarray, iters: int = 10) -> np.ndarray | None:
    i0 = 0
    i1 = int(np.argmax(np.sum((X - X[0]) ** 2, axis=1)))
    if i1 == i0:
        return None
    c = np.stack([X[i0], X[i1]])
    lab = np.zeros(len(X), dtype=int)
    for _ in range(iters):
        lab = np.argmin(((X[:, None, :] - c[None]) ** 2).sum(-1), axis=1)
        if lab.min() == lab.max():
            return None
        c = np.stack([X[lab == 0].mean(0), X[lab == 1].mean(0)])
    return lab if min((lab == 0).sum(), (lab == 1).sum()) >= 2 else None

sni/engrams.py:
"""Engram store: units and typed edges (spec §3).

Every *learned* array here (prototype φ and variance, strength s, edge weight w, eligibility e,
the BCM threshold) is kept read-only. The only way to change one is ``commit_*(idx, delta)``,
and the engine computes every ``delta`` with a registered, audited update function
(``sni.plasticity``). So a write that bypasses the Locality Rule raises instead of passing
silently (tested in ``tests/test_engrams.py``).

Structural bookkeeping (creating a unit or edge, flags such as maturity or lesioned, support
ledgers, provenance, the exemplar reservoir) is not a learned quantity in the sense of L1–L5:
it records events, it does not compute with another unit's parameters.
"""

from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass, field
from typing import Any, Iterator

import numpy as np

KINDS = ("percept", "word", "concept")


@contextmanager
def _writable(*arrays: np.ndarray) -> Iterator[None]:
    for a in arrays:
        a.flags.writeable = True
    try:
        yield
    finally:
        for a in arrays:
            a.flags.writeable = False


def _grow(a: np.ndarray, n: int) -> np.ndarray:
    out = np.zeros((n,) + a.shape[1:], dtype=a.dtype)
    out[: a.shape[0]] = a
    out.flags.writeable = False
    return out


@dataclass
class UnitMeta:
    kind: str
    level: int
    label: str | None = None  # word units: the word; others: None
    consolidated: bool = False
    alive: bool = True
    n_fires: int = 0
    last_novelty: float = 0.0
    recency: int = 0
    created: int = 0
    support: dict[str, float] = field(default_factory=dict)
    contra: float = 0.0
    exemplars: list[list[float]] = field(default_factory=list)
    provenance: list[tuple[int, str, int, float]] = field(default_factory=list)


class UnitStore:
    """N units over a ``dim``-wide feature/code space. Word units have φ = 0 (they are matched by
    label, not by features) and never enter percept matching."""

    def __init__(self, dim: int, reservoir: int = 4, var0: float = 0.02, s0: float = 0.5,
                 var_floor: float = 0.0) -> None:  # fmt: skip
        self.dim, self.reservoir, self.var0, self.s0 = int(dim), int(reservoir), var0, s0
        self.var_floor = float(var_floor)
        self.n = 0
        cap = 16
        self.phi = _grow(np.zeros((0, self.dim)), cap)
        self.var = _grow(np.zeros((0, self.dim)), cap)
        self.s = _grow(np.zeros(0), cap)
        self.bcm = _grow(np.zeros(0), cap)  # sliding BCM threshold per unit (post side)
        self.meta: list[UnitMeta] = []
        self.words: dict[str, int] = {}

    # --- structure --------------------------------------------------------------------------
    def _ensure(self, n: int) -> None:
        cap = self.phi.shape[0]
        if n <= cap:
            return
        new = max(n, 2 * cap)
        self.phi, self.var = _grow(self.phi, new), _grow(self.var, new)
        self.s, self.bcm = _grow(self.s, new), _grow(self.bcm, new)

    def add(
        self,
        kind: str,
        phi: np.ndarray | None,
        *,
        t: int = 0,
        level: int = 1,
        label: str | None = None,
    ) -> int:
        if kind not in KINDS:
            raise ValueError(f"unknown unit kind {kind!r}")
        i = self.n
        self._ensure(i + 1)
        with _writable(self.phi, self.var, self.s):
            self.phi[i] = 0.0 if phi is None else np.asarray(phi, dtype=float)
            self.var[i] = self.var0
            self.s[i] = self.s0
        self.meta.append(UnitMeta(kind=kind, level=level, label=label, created=t, recency=t))
        self.n += 1
        if kind == "word":
            if label is None or label in self.words:
                raise ValueError(f"word units need a new label, got {label!r}")
            self.words[label] = i
        return i

    def word(self, label: str, *, t: int = 0) -> int:
        """The unit of a heard word; a new token gets a new word unit (a symbol node)."""
        if label not in self.words:
            return self.add("word", None, t=t, label=label)
        return self.words[label]

    def ids(self, kind: str | None = None, *, level: int | None = None) -> np.ndarray:
        return np.array(
            [
                i
                for i, m in enumerate(self.meta)
                if m.alive
                and (kind is None or m.kind == kind)
                and (level is None or m.level == level)
            ],
            dtype=int,
        )

    def remember(self, i: int, x: np.ndarray, rng: np.random.Generator) -> None:
        """Reservoir sampling of raw exemplars (bytes counted; used by offline gates/render)."""
        m = self.meta[i]
        m.n_fires += 1
        if len(m.exemplars) < self.reservoir:
            m.exemplars.append([float(v) for v in x])
        else:
            j = int(rng.integers(m.n_fires))
            if j < self.reservoir:
                m.exemplars[j] = [float(v) for v in x]

    def kill(self, i: int) -> None:
        self.meta[i].alive = False

    # --- learned quantities: only through update-function deltas ----------------------------
    def commit_stats(self, idx: Any, delta: np.ndarray) -> None:
        """φ, var ← (φ, var) + Δ, Δ from ``update_prototype_stats`` / ``update_unit_episodic``."""
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        delta = np.asarray(delta).reshape(len(idx), 2, self.dim)
        with _writable(self.phi, self.var):
            self.phi[idx] += delta[:, 0]
            self.var[idx] = np.maximum(self.var[idx] + delta[:, 1], 0.0)

    def commit_strength(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.s):
            self.s[idx] = np.clip(self.s[idx] + np.asarray(delta), 0.0, 1.0)

    def commit_bcm(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.bcm):
            self.bcm[idx] += np.asarray(delta)

    def theta_stats(self, idx: Any) -> np.ndarray:
        """θ for the prototype update: stacked (φ, var), shape (len(idx), 2, dim)."""
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        return np.stack([self.phi[idx], self.var[idx]], axis=1)

    def nbytes(self, *, include_reservoir: bool = True) -> int:
        """Bytes of live units: φ + var (+ reservoir), float64."""
        live = [m for m in self.meta if m.alive and m.kind != "word"]
        total = len(live) * 2 * self.dim * 8 + len(self.ids()) * 2 * 8
        if include_reservoir:
            total += sum(
                len(m.exemplars) * (len(m.exemplars[0]) if m.exemplars else 0) * 8 for m in live
            )
        return total


@dataclass
class EdgeMeta:
    consolidated: bool = False
    lesioned: bool = False
    alive: bool = True
    support: dict[str, float] = field(default_factory=dict)  # teacher -> reliability-weighted +
    contra: float = 0.0
    created: int = 0
    provenance: list[tuple[int, str, int, float]] = field(default_factory=list)


class EdgeStore:
    """Typed, weighted, lesionable edges. Types come from the task's query frames (not learned)."""

    def __init__(self, types: tuple[str, ...]) -> None:
        if len(set(types)) != len(types) or not types:
            raise ValueError("relation types must be a non-empty set")
        self.types = tuple(types)
        self.n = 0
        cap = 32
        self.src = np.zeros(cap, dtype=int)
        self.dst = np.zeros(cap, dtype=int)
        self.rtype = np.zeros(cap, dtype=int)
        self.w = _grow(np.zeros(0), cap)
        self.e = _grow(np.zeros(0), cap)
        self.meta: list[EdgeMeta] = []
        self.index: dict[tuple[int, int, int], int] = {}
        self.out: dict[tuple[int, int], list[int]] = {}
        self.into: dict[tuple[int, int], list[int]] = {}

    def type_id(self, r: str) -> int:
        try:
            return self.types.index(r)
        except ValueError as exc:
            raise ValueError(f"unknown relation type {r!r}; known {self.types}") from exc

    def _ensure(self, n: int) -> None:
        cap = self.src.shape[0]
        if n <= cap:
            return
        new = max(n, 2 * cap)
        for name in ("src", "dst", "rtype"):
            a = getattr(self, name)
            b = np.zeros(new, dtype=int)
            b[: a.shape[0]] = a
            setattr(self, name, b)
        self.w, self.e = _grow(self.w, new), _grow(self.e, new)

    def get(self, src: int, r: str, dst: int) -> int | None:
        return self.index.get((int(src), self.type_id(r), int(dst)))

    def add(self, src: int, r: str, dst: int, *, t: int = 0) -> int:
        """A new provisional edge at w = 0 (its weight then comes only from update deltas)."""
        key = (int(src), self.type_id(r), int(dst))
        if key in self.index:
            idx = self.index[key]
            self.meta[idx].alive = True
            return idx
        idx = self.n
        self._ensure(idx + 1)
        self.src[idx], self.rtype[idx], self.dst[idx] = key
        self.meta.append(EdgeMeta(created=t))
        self.index[key] = idx
        self.out.setdefault((key[0], key[1]), []).append(idx)
        self.into.setdefault((key[2], key[1]), []).append(idx)
        self.n += 1
        return idx

    def outgoing(self, src: int, r: str, *, live_only: bool = True) -> list[int]:
        idx = self.out.get((int(src), self.type_id(r)), [])
        return [i for i in idx if self.meta[i].alive] if live_only else list(idx)

    def incoming(self, dst: int, r: str) -> list[int]:
        return [i for i in self.into.get((int(dst), self.type_id(r)), []) if self.meta[i].alive]

    def live(self) -> np.ndarray:
        return np.array([i for i in range(self.n) if self.meta[i].alive], dtype=int)

    def of_type(self, r: str) -> np.ndarray:
        rid = self.type_id(r)
        return np.array(
            [i for i in range(self.n) if self.meta[i].alive and self.rtype[i] == rid], dtype=int
        )

    def commit_w(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.w):
            np.add.at(self.w, idx, np.asarray(delta, dtype=float) * np.ones(len(idx)))
            self.w[idx] = np.clip(self.w[idx], 0.0, 1.0)

    def commit_e(self, idx: Any, delta: Any) -> None:
        idx = np.atleast_1d(np.asarray(idx, dtype=int))
        with _writable(self.e):
            self.e[idx] += np.asarray(delta, dtype=float) * np.ones(len(idx))

    def kill(self, idx: int) -> None:
        self.meta[idx].alive = False

    def nbytes(self) -> int:
        return len(self.live()) * (2 * 8 + 3 * 8)  # w, e (+ src, dst, type)

sni/locality_audit.py:
"""Locality audit: enforcement of the SNI Locality Rule (L1-L5) on every update function.

The rule (Lead Synthesis 02 §3): every change to a learned quantity is
    Δθ = F(u_pre, u_post, θ, e_θ, m_t)
plus, as the single declared exception (L3), a binary selection ``tag``. This module checks it
in two layers, and CI fails if either fails (``python -m sni.locality_audit`` exits non-zero):

STATIC  (AST of the function source)
  * positional parameters are drawn from ALLOWED_ARGS (+ ``tag``); everything else must be a
    keyword-only *hyper-parameter* with a numeric/bool default (a constant, not data);
  * every parameter is annotated (float / int / bool / np.ndarray);
  * the body touches no free name except an allow-listed builtin, ``np``/``math`` attributes from
    an allow-list, or another registered update function (so: no module globals, no ``self``,
    no ``open``/``getattr``/``globals``, no ``np.random``, no imports, no ``global``);
  * attribute access on a parameter is limited to array-shape/reduction attributes, so a
    parameter cannot be used to reach another object;
  * every top-level ``update_*`` function in an audited module is registered.

RUNTIME  (black-box, on probes generated from the signature)
  * determinism, also under a reseeded global RNG, and the global RNG state is not consumed;
  * inputs are not mutated and module globals are not mutated;
  * output does not depend on module-level data (all numeric/array globals are scrambled);
  * shuffled-input test: a batch of B independent instances is evaluated; permuting the
    instances permutes the output identically, and replacing instance j leaves every other
    output bit-identical (zero cross-talk, i.e. no dependence on anything outside the allowed
    inputs of that instance).

Inference (settling, spreading, NNLS) is not learning and is not audited here (rule, last
paragraph); only functions that write a learned quantity are registered.
"""

from __future__ import annotations

import ast
import builtins
import copy
import importlib
import inspect
import sys
import textwrap
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

import numpy as np

ALLOWED_ARGS: tuple[str, ...] = ("u_pre", "u_post", "theta", "e_theta", "m_t")
TAG_ARG = "tag"  # L3: binary selection tag, no magnitude
ALLOWED_POSITIONAL = ALLOWED_ARGS + (TAG_ARG,)

_ALLOWED_BUILTINS = {"float", "int", "bool", "abs", "min", "max"}
_ALLOWED_NP_ATTRS = {
    "abs", "asarray", "clip", "exp", "float64", "log", "maximum", "minimum", "ndarray",
    "ones_like", "sqrt", "stack", "sum", "where", "zeros_like",
}  # fmt: skip
_ALLOWED_MATH_ATTRS = {"exp", "log", "sqrt"}
_ALLOWED_PARAM_ATTRS = {"shape", "size", "ndim", "dtype", "T", "sum", "copy", "astype"}
_ALLOWED_ANNOTATIONS = {"float", "int", "bool", "ndarray", "np.ndarray"}

# modules whose update functions CI audits; extend as the build order adds mechanisms
AUDITED_MODULES: tuple[str, ...] = ("sni.plasticity", "sni.perception")


class LocalityViolation(AssertionError):  # noqa: N818
    """Raised by :func:`assert_local` when an update function breaks the rule."""


@dataclass(frozen=True)
class UpdateSpec:
    name: str
    fn: Callable[..., Any]
    core_shapes: dict[str, tuple[int, ...]]


REGISTRY: dict[str, UpdateSpec] = {}


def update_function(
    fn: Callable[..., Any] | None = None, *, core_shapes: dict[str, tuple[int, ...]] | None = None
) -> Any:
    """Register ``fn`` as a learned-quantity update. ``core_shapes`` gives the per-instance shape
    of array arguments for the probes (default: scalar for float/int/bool, ``(4,)`` for ndarray).
    """

    def register(f: Callable[..., Any]) -> Callable[..., Any]:
        if f.__name__ in REGISTRY and REGISTRY[f.__name__].fn is not f:
            raise ValueError(f"duplicate update function name {f.__name__!r}")
        REGISTRY[f.__name__] = UpdateSpec(f.__name__, f, dict(core_shapes or {}))
        return f

    return register if fn is None else register(fn)


# --------------------------------------------------------------------------------------------
# static layer
# --------------------------------------------------------------------------------------------
def _annotation_name(ann: Any) -> str:
    if ann is inspect.Parameter.empty:
        return ""
    if isinstance(ann, str):
        return ann.replace(" ", "")
    return getattr(ann, "__name__", str(ann))


def _function_ast(fn: Callable[..., Any]) -> ast.FunctionDef:
    src = textwrap.dedent(inspect.getsource(fn))
    tree = ast.parse(src)
    node = tree.body[0]
    if not isinstance(node, ast.FunctionDef):
        raise LocalityViolation(f"{fn!r} is not a plain function")
    return node


def static_violations(fn: Callable[..., Any]) -> list[str]:
    """Return the static violations of ``fn`` (empty list = clean)."""
    out: list[str] = []
    name = fn.__name__
    sig = inspect.signature(fn)

    kw_only = {p.name for p in sig.parameters.values() if p.kind is p.KEYWORD_ONLY}
    for p in sig.parameters.values():
        if p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
            out.append(f"{name}: *args/**kwargs hide inputs from the audit ({p.name})")
            continue
        if _annotation_name(p.annotation) not in _ALLOWED_ANNOTATIONS:
            out.append(
                f"{name}: parameter {p.name!r} needs an annotation in {_ALLOWED_ANNOTATIONS}"
            )
        if p.name in kw_only:
            if p.default is p.empty or not isinstance(p.default, (int, float, bool)):
                out.append(f"{name}: hyper-parameter {p.name!r} needs a numeric/bool default")
            if p.name in ALLOWED_POSITIONAL:
                out.append(f"{name}: {p.name!r} must be positional, not a hyper-parameter")
        elif p.name not in ALLOWED_POSITIONAL:
            out.append(
                f"{name}: argument {p.name!r} is not in the Locality Rule set "
                f"{ALLOWED_POSITIONAL}; pass constants as keyword-only hyper-parameters"
            )
        if p.name == TAG_ARG and _annotation_name(p.annotation) != "bool":
            out.append(f"{name}: the selection tag must be bool (no magnitude)")

    try:
        node = _function_ast(fn)
    except (OSError, TypeError, SyntaxError) as exc:  # pragma: no cover - source unavailable
        return out + [f"{name}: cannot read source for the audit ({exc})"]

    params = {p.name for p in sig.parameters.values()}
    local: set[str] = set(params)
    loads: set[str] = set()
    # only the body is audited: decorators and annotations are not executed as part of Δθ
    body_nodes = [sub for stmt in node.body for sub in ast.walk(stmt)]
    for sub in body_nodes:
        if isinstance(sub, ast.Name):
            (local if isinstance(sub.ctx, ast.Store) else loads).add(sub.id)
        elif isinstance(sub, (ast.Global, ast.Nonlocal)):
            out.append(f"{name}: global/nonlocal statements are forbidden")
        elif isinstance(sub, (ast.Import, ast.ImportFrom)):
            out.append(f"{name}: imports inside an update function are forbidden")
        elif isinstance(sub, ast.arg):
            local.add(sub.arg)

    allowed_names = _ALLOWED_BUILTINS | {"np", "math"} | set(REGISTRY)
    for free in sorted(loads - local):
        if free not in allowed_names:
            hint = "builtin" if hasattr(builtins, free) else "module-level name"
            out.append(f"{name}: reads forbidden {hint} {free!r}")

    for sub in body_nodes:
        if not isinstance(sub, ast.Attribute) or not isinstance(sub.value, ast.Name):
            continue
        base, attr = sub.value.id, sub.attr
        if base == "np" and attr not in _ALLOWED_NP_ATTRS:
            out.append(f"{name}: np.{attr} is not on the audit allow-list")
        elif base == "math" and attr not in _ALLOWED_MATH_ATTRS:
            out.append(f"{name}: math.{attr} is not on the audit allow-list")
        elif base in params and attr not in _ALLOWED_PARAM_ATTRS:
            out.append(f"{name}: attribute {base}.{attr} may reach another object")
    return out


def module_registration_violations(module_name: str) -> list[str]:
    """Every top-level ``update_*`` function of the module must be decorated and registered."""
    module = importlib.import_module(module_name)
    src_file = inspect.getsourcefile(module)
    if src_file is None:  # pragma: no cover
        return [f"{module_name}: no source file"]
    tree = ast.parse(Path(src_file).read_text())
    out: list[str] = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and node.name.startswith("update_"):
            decorated = any(
                (isinstance(d, ast.Name) and d.id == "update_function")
                or (
                    isinstance(d, ast.Call)
                    and isinstance(d.func, ast.Name)
                    and d.func.id == "update_function"
                )
                for d in node.decorator_list
            )
            if not decorated or node.name not in REGISTRY:
                out.append(f"{module_name}.{node.name}: update function is not registered/audited")
    return out


# --------------------------------------------------------------------------------------------
# runtime layer
# --------------------------------------------------------------------------------------------
_BATCH = 6
_ARRAY_LEN = 4


def _kind(p: inspect.Parameter) -> str:
    name = _annotation_name(p.annotation)
    return "array" if "ndarray" in name else ("bool" if name == "bool" else "scalar")


def _draw(rng: np.random.Generator, pname: str, kind: str, shape: tuple[int, ...]) -> Any:
    if kind == "bool":
        return rng.random(shape) < 0.5
    if pname == "m_t":
        return rng.normal(size=shape)
    return rng.random(shape)  # activities, weights and traces live in [0, 1]


def _instances(
    fn: Callable[..., Any], core: dict[str, tuple[int, ...]], rng: np.random.Generator, batch: int
) -> dict[str, Any]:
    args: dict[str, Any] = {}
    for p in inspect.signature(fn).parameters.values():
        if p.kind is p.KEYWORD_ONLY:
            continue
        kind = _kind(p)
        shape = core.get(p.name, (_ARRAY_LEN,) if kind == "array" else ())
        args[p.name] = _draw(rng, p.name, kind, (batch,) + shape)
    return args


def _take(args: dict[str, Any], idx: Any) -> dict[str, Any]:
    return {k: v[idx] for k, v in args.items()}


def runtime_violations(
    fn: Callable[..., Any], core_shapes: dict[str, tuple[int, ...]] | None = None, seed: int = 0
) -> list[str]:
    """Black-box checks on probes generated from the signature (see module docstring)."""
    out: list[str] = []
    name = fn.__name__
    core = dict(core_shapes or {})
    rng = np.random.default_rng(seed)
    args = _instances(fn, core, rng, _BATCH)
    base = fn(**copy.deepcopy(args))

    # determinism, with a differently seeded global RNG, and no RNG consumption
    state_before = np.random.get_state()
    np.random.seed(12345)
    again = fn(**copy.deepcopy(args))
    np.random.seed(54321)
    third = fn(**copy.deepcopy(args))
    np.random.set_state(state_before)
    if not (np.array_equal(base, again) and np.array_equal(base, third)):
        out.append(f"{name}: output depends on something other than its arguments (RNG/state)")
    probe_state = np.random.get_state()
    fn(**copy.deepcopy(args))
    after_state = np.random.get_state()
    if not all(np.array_equal(a, b) for a, b in zip(probe_state, after_state)):
        out.append(f"{name}: consumes the global RNG")

    # inputs and module globals are not mutated
    frozen = copy.deepcopy(args)
    fn(**args)
    if any(not np.array_equal(frozen[k], args[k]) for k in args):
        out.append(f"{name}: mutates its inputs")
    g = fn.__globals__
    ids = {k: id(v) for k, v in g.items()}
    fn(**copy.deepcopy(args))
    if ids != {k: id(v) for k, v in g.items()}:
        out.append(f"{name}: rebinds module globals")

    # no dependence on module-level data: scramble every data-like global, restore afterwards
    saved = {}
    for k, v in list(g.items()):
        if k.startswith("__"):
            continue
        if isinstance(v, (int, float, np.ndarray, list, dict, tuple)) and not isinstance(v, bool):
            saved[k] = v
    try:
        for k, v in saved.items():
            if isinstance(v, np.ndarray):
                g[k] = rng.normal(size=v.shape)
            elif isinstance(v, (int, float)):
                g[k] = v + 1234.5
            else:
                g[k] = None
        scrambled = fn(**copy.deepcopy(args))
    except Exception:  # noqa: BLE001 - a crash under scrambled globals is itself a dependence
        scrambled = None
    finally:
        g.update(saved)
    if scrambled is None or not np.array_equal(base, scrambled):
        out.append(f"{name}: output changes when module-level data is scrambled")

    # shuffled-input test: permutation equivariance and zero cross-talk between instances
    perm = rng.permutation(_BATCH)
    permuted = fn(**_take(copy.deepcopy(args), perm))
    if not np.array_equal(np.asarray(base)[perm], permuted):
        out.append(f"{name}: shuffling the instances does not shuffle the outputs (coupled)")
    j = int(rng.integers(_BATCH))
    other = _instances(fn, core, rng, _BATCH)
    changed = copy.deepcopy(args)
    for k in changed:
        changed[k][j] = other[k][j]
    alt = np.asarray(fn(**changed))
    mask = np.arange(_BATCH) != j
    if not np.array_equal(np.asarray(base)[mask], alt[mask]):
        out.append(f"{name}: instance j influences the output of other instances (cross-talk)")
    return out


# --------------------------------------------------------------------------------------------
# entry points
# --------------------------------------------------------------------------------------------
def audit_function(
    fn: Callable[..., Any], core_shapes: dict[str, tuple[int, ...]] | None = None
) -> list[str]:
    """All violations (static + runtime) of one function; works on unregistered functions too."""
    found = static_violations(fn)
    if not found:  # runtime probes are only meaningful for a well-formed signature
        found += runtime_violations(fn, core_shapes)
    return found


def audit_all(modules: tuple[str, ...] = AUDITED_MODULES) -> dict[str, list[str]]:
    """Audit every registered update function of the audited modules. Empty lists = clean."""
    report: dict[str, list[str]] = {}
    for module_name in modules:
        importlib.import_module(module_name)
        missing = module_registration_violations(module_name)
        if missing:
            report[module_name] = missing
    for spec in REGISTRY.values():
        report[spec.name] = audit_function(spec.fn, spec.core_shapes)
    if not REGISTRY:
        report["<registry>"] = ["no update functions registered: nothing was audited"]
    return report


def assert_local(
    fn: Callable[..., Any], core_shapes: dict[str, tuple[int, ...]] | None = None
) -> None:
    found = audit_function(fn, core_shapes)
    if found:
        raise LocalityViolation("; ".join(found))


def main() -> int:
    report = audit_all()
    bad = {k: v for k, v in report.items() if v}
    for name, problems in sorted(report.items()):
        print(("FAIL " if problems else "ok   ") + name)
        for problem in problems:
            print("     - " + problem)
    print(f"\n{len(report) - len(bad)}/{len(report)} clean")
    return 1 if bad else 0


if __name__ == "__main__":
    # Re-import under the canonical name: running with ``-m`` creates a second copy of this
    # module as ``__main__``, whose REGISTRY would stay empty because sni.plasticity registers
    # into ``sni.locality_audit``.
    from sni.locality_audit import main as _canonical_main

    sys.exit(_canonical_main())

sni/novelty.py:
"""Internal signals (spec §1.5 glossary). Three separate quantities, never aliased:

* **novelty**  ν — energy of the *static* memory model against the input
  (ν = −log Σᵢ πᵢ exp(−Eᵢ/2)); gates formation and question choice, never enters m_t;
* **surprise** γ_BF — temporal prediction error in Bayes-factor form, on the stream of outcomes;
  sets the learning rate through m_t;
* **expected uncertainty** — learned precision (1/var), stored per prototype in ``engrams``.

Plus the novelty *profile* (ε₀, ε₁, margin, ν) of spec §4 step 3 and its fixed readout.
Everything here is inference: it reads stored records, it writes nothing.
"""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np

PROFILE_CLASSES = ("known", "ambiguous", "composite", "novel")


@dataclass(frozen=True)
class Profile:
    eps0: float  # best single-unit prediction error (per dimension)
    eps1: float  # residual error after explaining-away over the top-m units (NNLS)
    margin: float  # energy gap between the best two units with different answers
    nu: float  # novelty energy of the static model
    best: int  # best unit id (-1: empty store)

    def as_vector(self) -> np.ndarray:
        return np.array([self.eps0, self.eps1, self.margin, self.nu])


EMPTY_PROFILE = Profile(np.inf, np.inf, 0.0, np.inf, -1)


def nnls(A: np.ndarray, b: np.ndarray, max_iter: int = 50) -> np.ndarray:
    """Lawson–Hanson non-negative least squares, min ‖A c − b‖ s.t. c ≥ 0 (A: d × m, m small)."""
    m = A.shape[1]
    c = np.zeros(m)
    passive = np.zeros(m, dtype=bool)
    for _ in range(max_iter):
        grad = A.T @ (b - A @ c)
        if passive.all() or grad[~passive].max(initial=-np.inf) <= 1e-10:
            break
        j = int(np.argmax(np.where(passive, -np.inf, grad)))
        passive[j] = True
        while True:
            s = np.zeros(m)
            s[passive] = np.linalg.lstsq(A[:, passive], b, rcond=None)[0]
            if (s[passive] > 0).all():
                c = s
                break
            neg = passive & (s <= 0)
            alpha = np.min(c[neg] / (c[neg] - s[neg] + 1e-15))
            c = c + alpha * (s - c)
            passive &= c > 1e-12
    return c


def novelty_energy(energy: np.ndarray, counts: np.ndarray) -> float:
    """ν = −log Σ πᵢ exp(−Eᵢ/2), πᵢ ∝ counts (static-model energy; glossary)."""
    if energy.size == 0:
        return float("inf")
    pi = (counts + 1.0) / np.sum(counts + 1.0)
    x = -energy / 2.0 + np.log(pi)
    top = np.max(x)
    return float(-(top + np.log(np.sum(np.exp(x - top)))))


def competition_margin(energy: np.ndarray, answers: list[int]) -> float:
    """E₍₂₎ − E₍₁₎ over units whose answers differ (Candidate A §3 step 5). With fewer than two
    distinct answers the margin is +inf (no competitor)."""
    order = np.argsort(energy)
    if order.size == 0:
        return 0.0
    first = answers[order[0]]
    for j in order[1:]:
        if answers[j] != first or first == -1:
            return float(energy[j] - energy[order[0]])
    return float("inf")


def classify_profile(p: Profile, *, theta_novel: float, theta_composite: float,
                     theta_margin: float) -> str:  # fmt: skip
    """Fixed readout of the profile into known / ambiguous / composite / novel.

    novel: nothing explains the input, alone or in combination; composite: no single unit does
    but a non-negative mix of known units does (a new combination of known parts); ambiguous:
    explained, but two different answers compete within the margin."""
    if p.best < 0:
        return "novel"
    if p.eps0 > theta_novel:
        return "composite" if p.eps1 <= theta_composite else "novel"
    if p.margin < theta_margin:
        return "ambiguous"
    return "known"


def bayes_factor_surprise(p_observed: float, p_prior: float, pc: float) -> float:
    """γ = m·S/(1 + m·S), S = p₀(outcome)/p_t(outcome), m = p_c/(1 − p_c) (card 08 §3d).

    γ ∈ [0, 1): ≈ 0 when the model predicted the outcome, → 1 when it was very unlikely."""
    if not 0.0 < p_observed <= 1.0 or not 0.0 < p_prior <= 1.0:
        raise ValueError("probabilities must be in (0, 1]")
    s = p_prior / p_observed
    m = pc / (1.0 - pc)
    return float(m * s / (1.0 + m * s))


def auroc(scores_pos: np.ndarray, scores_neg: np.ndarray) -> float:
    """P(score of a positive > score of a negative), ties count ½ (Mann–Whitney)."""
    pos, neg = np.asarray(scores_pos, float), np.asarray(scores_neg, float)
    if pos.size == 0 or neg.size == 0:
        raise ValueError("need positives and negatives")
    diff = pos[:, None] - neg[None, :]
    return float(np.mean((diff > 0) + 0.5 * (diff == 0)))

sni/plasticity.py:
"""Plasticity: every update to a learned quantity, with all plasticity switches (spec §2, §5).

Two kinds of function live here:

* **update functions** (``update_*``, registered with ``@update_function``): they return the
  increment Δθ (or Δe for the trace) and are expressed *only* through
  ``(u_pre, u_post, theta, e_theta, m_t)`` plus the binary selection ``tag`` and keyword-only
  numeric hyper-parameters. ``sni.locality_audit`` enforces this statically and at runtime, and
  CI fails otherwise. They are elementwise over leading batch dimensions, so the engine can
  vectorise over many synapses/units and the audit can shuffle them.
* **helpers** (everything else): the modulator m_t (a broadcast scalar, L2), the running
  baselines it needs, clipping, and :func:`select_updaters`, which maps a :class:`SNIConfig`
  onto the right update functions. Helpers write no learned quantity.

Interpretations the lead should confirm (also listed in the Phase 4 Build Report):

* Heterosynaptic normalisation takes ``theta`` = the *source unit's own* outgoing weight vector.
  These are the unit's own synapses, so this is read as local to that unit (L1).
* The BCM sliding threshold is carried in ``e_theta`` (metaplastic state travelling with θ) and
  is tracked by :func:`update_bcm_threshold` from the post unit's own activity.
* ``novelty`` never enters m_t (spec §5): it only gates formation and question choice.
"""

from __future__ import annotations

import math
from dataclasses import dataclass
from typing import Any, Callable

import numpy as np

from sni.config import SNIConfig
from sni.locality_audit import update_function

# ============================================================================================
# update functions (audited)
# ============================================================================================


@update_function
def update_trace(u_pre: float, u_post: float, e_theta: float, *, tau: float = 3.0) -> float:
    """Δe for e ← e·exp(−1/τ) + u_pre·u_post (spec §4.8). τ = 0 keeps no memory: e ← u_pre·u_post.

    With ``trace_tau=0`` and ``feedback=bare`` this is the v1 rule R0 of card 03 (no trace).
    """
    decay = math.exp(-1.0 / tau) if tau > 0 else 0.0
    return e_theta * (decay - 1.0) + u_pre * u_post


@update_function
def update_edge_named(m_t: float, tag: bool, *, eta: float = 0.1) -> float:
    """feedback=named: Δw = η·m_t·1[edge ∈ path(proposition)]. ``tag`` is the L3 selection tag."""
    return eta * m_t * tag


@update_function
def update_edge_bare(e_theta: float, m_t: float, *, eta: float = 0.1) -> float:
    """feedback=bare: Δw = η·m_t·e (credit by the edge's own eligibility trace)."""
    return eta * m_t * e_theta


@update_function(core_shapes={"theta": (4,)})
def update_normalize_none(theta: np.ndarray) -> np.ndarray:
    """normalization=none."""
    return np.zeros_like(theta)


@update_function(core_shapes={"theta": (4,)})
def update_normalize_heterosynaptic(theta: np.ndarray, *, cap: float = 1.0) -> np.ndarray:
    """normalization=heterosynaptic: ``theta`` is one source unit's outgoing weights (last axis);
    if their sum exceeds ``cap`` they are scaled down together, preserving their ratios."""
    total = np.sum(theta, axis=-1, keepdims=True)
    scale = np.where(total > cap, cap / np.maximum(total, 1e-12), 1.0)
    return theta * scale - theta


@update_function
def update_bcm_threshold(u_post: float, e_theta: float, *, tau: float = 100.0) -> float:
    """Δ of the sliding BCM threshold θ_M (kept in ``e_theta``): θ_M tracks E[u_post²]."""
    return (u_post * u_post - e_theta) / tau


@update_function
def update_normalize_bcm(
    u_pre: float, u_post: float, e_theta: float, *, rate: float = 0.01
) -> float:
    """normalization=bcm: depression when the post unit is above its sliding threshold
    (``e_theta`` = θ_M); zero otherwise. Stabilising half of BCM, applied after every update."""
    return -rate * u_pre * u_post * np.maximum(u_post - e_theta, 0.0)


@update_function(core_shapes={"u_pre": (4,), "theta": (2, 4)})
def update_prototype_stats(
    u_pre: np.ndarray, theta: np.ndarray, m_t: float, *, eta: float = 0.1
) -> np.ndarray:
    """store=prototype. ``theta[..., 0, :]`` = φ, ``theta[..., 1, :]`` = per-dim variance;
    ``u_pre`` = the input x. Δφ = η·m⁺·(x − φ); Δvar = η·m⁺·((x − φ)² − var). Both are driven
    only by the unit's own mismatch with its prediction (L1)."""
    # the gain is capped at 1 so a large modulator can at most move φ onto x (no overshoot)
    gain = np.asarray(np.minimum(eta * np.maximum(m_t, 0.0), 1.0))[..., None]
    err = u_pre - theta[..., 0, :]
    return np.stack([gain * err, gain * (err * err - theta[..., 1, :])], axis=-2)


@update_function(core_shapes={"u_pre": (4,), "theta": (2, 4)})
def update_unit_episodic(u_pre: np.ndarray, theta: np.ndarray, m_t: float) -> np.ndarray:
    """store=episodic: traces are never edited, ever (spec §5)."""
    return np.zeros_like(theta)


@update_function
def update_strength(u_post: float, theta: float, m_t: float, *, rate: float = 0.1) -> float:
    """Unit strength s ∈ [0, 1]: potentiated by a positive modulator, depressed by a negative one,
    in proportion to the unit's own participation ``u_post`` (soft-bounded, so s stays in [0, 1]).
    """
    return rate * u_post * (np.maximum(m_t, 0.0) * (1.0 - theta) - np.maximum(-m_t, 0.0) * theta)


@update_function
def update_downscale(theta: float, *, rho: float = 0.05) -> float:
    """Offline downscaling of a provisional edge weight (consolidation pass, spec §5)."""
    return -rho * theta


# ============================================================================================
# helpers (write no learned quantity)
# ============================================================================================


def apply_delta(theta: Any, delta: Any, lo: float = 0.0, hi: float = 1.0) -> Any:
    """θ ← clip(θ + Δθ). Weights live in [0, 1] (spec §3)."""
    return np.clip(np.asarray(theta) + np.asarray(delta), lo, hi)


def precision_from_var(var: np.ndarray, eps: float = 1e-6) -> np.ndarray:
    """Per-dimension precision of a prototype."""
    return 1.0 / (np.asarray(var) + eps)


def log_det_precision(var: np.ndarray, eps: float = 1e-6) -> float:
    """log-det of the (diagonal) precision matrix, tracked per unit (spec §3)."""
    return float(-np.sum(np.log(np.asarray(var) + eps)))


def effective_eta(maturity: str, eta: float, eta_c: float) -> float:
    """Consolidated units/edges learn at η_c ≪ η (spec §5)."""
    if maturity not in ("provisional", "consolidated"):
        raise ValueError(f"unknown maturity {maturity!r}")
    return eta_c if maturity == "consolidated" else eta


def compute_modulator(
    f: int,
    *,
    q_teacher: float,
    gamma_bf: float,
    b_bar: float,
    kappa: float,
    terms: tuple[str, ...],
) -> float:
    """m_t = q_T · (1 + κ·γ_BF) · (f − b̄), restricted to the enabled modulator terms.

    ``f`` must be exactly ±1 (the only teaching signal). Without ``reliability`` q_T is 1;
    without ``surprise`` γ_BF is 0. ``novelty`` never enters the magnitude (spec §5).
    """
    if f not in (-1, 1):
        raise ValueError(f"teaching signal must be +1 or -1, got {f!r}")
    if "teacher" not in terms:
        raise ValueError("modulator without 'teacher' is incoherent")
    if not 0.0 <= q_teacher <= 1.0:
        raise ValueError("teacher reliability q must be in [0, 1]")
    if gamma_bf < 0.0:
        raise ValueError("Bayes-factor surprise must be >= 0")
    q = q_teacher if "reliability" in terms else 1.0
    gamma = gamma_bf if "surprise" in terms else 0.0
    return q * (1.0 + kappa * gamma) * (f - b_bar)


class RunningBaseline:
    """b̄: running mean of the ±1 judgement f, keyed according to the ``centering`` switch.

    * ``none``                  — b̄ ≡ 0 (uncentred; the v1 rule of card 03)
    * ``per_context``           — one mean per context key
    * ``per_proposition_type``  — one mean per proposition type (never per teacher verdict)

    Modulator-side state: it feeds m_t (L2) and is not a learned parameter θ.
    """

    def __init__(self, mode: str, rate: float = 0.05) -> None:
        if mode not in ("none", "per_context", "per_proposition_type"):
            raise ValueError(f"unknown centering {mode!r}")
        self.mode, self.rate = mode, rate
        self._stats: dict[Any, tuple[float, int]] = {}

    def _key(self, context: Any, ptype: Any) -> Any:
        return context if self.mode == "per_context" else ptype

    def value(self, *, context: Any = None, ptype: Any = None) -> float:
        if self.mode == "none":
            return 0.0
        return self._stats.get(self._key(context, ptype), (0.0, 0))[0]

    def observe(self, f: int, *, context: Any = None, ptype: Any = None) -> None:
        if f not in (-1, 1):
            raise ValueError(f"teaching signal must be +1 or -1, got {f!r}")
        if self.mode == "none":
            return
        key = self._key(context, ptype)
        mean, n = self._stats.get(key, (0.0, 0))
        n += 1
        self._stats[key] = (mean + max(1.0 / n, self.rate) * (f - mean), n)


@dataclass(frozen=True)
class Updaters:
    """The update functions selected by one config (switch → function), plus their constants."""

    feedback: str
    trace_tau: int
    store: str
    normalization: str
    eta: float
    eta_phi: float
    eta_c: float
    weight_cap: float
    bcm_rate: float
    bcm_tau: float
    unit: Callable[..., Any]
    normalize: Callable[..., Any]

    @property
    def uses_trace(self) -> bool:
        """Eligibility traces are needed only when the feedback does not name the proposition."""
        return self.feedback == "bare"

    def trace_delta(self, u_pre: Any, u_post: Any, e_theta: Any) -> Any:
        return update_trace(u_pre, u_post, e_theta, tau=float(self.trace_tau))

    def edge_delta(
        self, *, m_t: Any, e_theta: Any = None, tag: Any = None, eta: float | None = None
    ) -> Any:
        eta = self.eta if eta is None else eta
        if self.feedback == "named":
            if tag is None:
                raise ValueError("feedback=named needs the selection tag of the judged path")
            return update_edge_named(m_t, tag, eta=eta)
        if e_theta is None:
            raise ValueError("feedback=bare needs the edge eligibility trace")
        return update_edge_bare(e_theta, m_t, eta=eta)

    def normalize_delta(
        self, theta: Any, *, u_pre: Any = None, u_post: Any = None, e_theta: Any = None
    ) -> Any:
        """Δθ of the normalisation step. ``theta`` is a source unit's outgoing weights (last axis)
        for heterosynaptic; BCM needs the post activity and the threshold in ``e_theta``."""
        if self.normalization == "bcm":
            if u_pre is None or u_post is None or e_theta is None:
                raise ValueError("normalization=bcm needs u_pre, u_post and the threshold e_theta")
            return update_normalize_bcm(u_pre, u_post, e_theta, rate=self.bcm_rate)
        if self.normalization == "heterosynaptic":
            return update_normalize_heterosynaptic(theta, cap=self.weight_cap)
        return update_normalize_none(theta)

    def bcm_threshold_delta(self, u_post: Any, threshold: Any) -> Any:
        return update_bcm_threshold(u_post, threshold, tau=self.bcm_tau)

    def unit_delta(self, x: Any, theta: Any, m_t: Any, *, eta: float | None = None) -> Any:
        if self.store == "episodic":
            return update_unit_episodic(x, theta, m_t)
        return update_prototype_stats(x, theta, m_t, eta=self.eta_phi if eta is None else eta)


def select_updaters(cfg: SNIConfig) -> Updaters:
    """Map every plasticity switch of ``cfg`` onto its update function."""
    p = cfg.params
    return Updaters(
        feedback=cfg.feedback,
        trace_tau=cfg.trace_tau,
        store=cfg.store,
        normalization=cfg.normalization,
        eta=p.eta,
        eta_phi=p.eta_phi,
        eta_c=p.eta_c,
        weight_cap=p.weight_cap,
        bcm_rate=p.bcm_rate,
        bcm_tau=p.bcm_tau,
        unit=update_unit_episodic if cfg.store == "episodic" else update_prototype_stats,
        normalize={
            "none": update_normalize_none,
            "heterosynaptic": update_normalize_heterosynaptic,
            "bcm": update_normalize_bcm,
        }[cfg.normalization],
    )


def make_baseline(cfg: SNIConfig) -> RunningBaseline:
    return RunningBaseline(cfg.centering, cfg.params.baseline_rate)

lex/plasticity.py:
"""Plasticity of the letters-up reader (``lex``). Every learned quantity of the reader changes only
through these registered update functions, audited by ``sni.locality_audit`` exactly like the
concept engine's rules (Δθ = F(u_pre, u_post, θ, e_θ, m_t)).

Learned quantities of the reader:
* letter-transition edges  (context engram → next letter): co-activation counts;
* word engram familiarity   (how often a form has been read);
* word context vectors      (the reader's OWN embedding): Hebbian accumulation of the identity
  codes of the words that fire around it, minus a slow decay;
* word→word association and word→next-word edges: co-activation counts;
* relation-cue edges        (between-words pattern → relation): ±1-modulated Hebbian.
"""

from __future__ import annotations

import numpy as np

from sni.locality_audit import update_function


@update_function
def update_cooccurrence(u_pre: float, u_post: float, *, eta: float = 1.0) -> float:
    """Δw = η·u_pre·u_post. Letter-transition edges, word→next-word and association edges: a
    synapse grows each time its pre and post units fire together (plain Hebbian count)."""
    return eta * u_pre * u_post


@update_function
def update_familiarity(u_post: float, theta: float, *, rate: float = 0.05) -> float:
    """Δf = rate·u_post·(1 − f): a word engram's familiarity saturates towards 1 with exposure."""
    return rate * u_post * (1.0 - theta)


@update_function(core_shapes={"u_pre": (4,), "theta": (4,)})
def update_context(
    u_pre: np.ndarray, u_post: float, theta: np.ndarray, *, eta: float = 1.0, decay: float = 0.0
) -> np.ndarray:
    """Δc = η·u_post·u_pre − decay·u_post·c. ``u_pre`` is the summed (habituated) identity code of
    the neighbouring words that fired with this word; ``theta`` its own context vector."""
    post = np.asarray(u_post)[..., None]
    return eta * post * u_pre - decay * post * theta


@update_function
def update_relation_cue(u_pre: float, m_t: float, theta: float, *, eta: float = 0.5,
                        cap: float = 5.0) -> float:  # fmt: skip
    """Δw = η·m_t·u_pre, clipped to [−cap, cap]: a between-words pattern that was present when a
    teacher judged a proposed relation (m_t = ±1, scaled by surprise) becomes a cue for it."""
    return np.clip(theta + eta * m_t * u_pre, -cap, cap) - theta

lex/mind.py:
"""Mind = the letters-up reader (``lex.reader``) + the SNI concept engine (``sni.engine.Brain``).

* The reader grows its own meaning vectors from letters and reading. The Brain perceives a word
  through that vector: no GloVe, no pretrained network anywhere.
* Teaching is the Brain's ±1 protocol, unchanged (query → hear → feedback).
* Metacognition, kept as separate signals because "I don't understand" has kinds:
    form      — never read this string; is it even word-like? does it look like a word I know?
    exposure  — read it, but too rarely to know what it is like;
    meaning   — I know what it is like, but not what it is (no name) / two names compete;
    relation  — I know what it is, but not how it connects (no edge on the asked path);
    surprise  — a sentence went against what I predicted.
* Connections: the Mind proposes links itself, from reading — "zebra reads like horse and
  giraffe: is it a mammal?" and, once one relation is confirmed, "the words between 'fish' and
  'water' were 'live in'; 'birds live in the sky' has them too: does bird lives-in sky?". The
  teacher only says ±1. When the Mind proposes a word for its own open question, the word comes
  from the Mind (its reading), never from the teacher.
"""

from __future__ import annotations

import math
from typing import Any

import numpy as np

from lex.plasticity import update_relation_cue
from lex.reader import Reader
from sni.config import SNIConfig
from sni.engine import Brain
from sni.frames import FRAMES, Frame

FRAMES.setdefault("IS-A-2", Frame("IS-A-2", ("named", "is-a", "is-a")))
MIND_FRAMES = ("WHAT-IS", "IS-A", "IS-A-2", "HAS", "LIVES-IN", "IS-A/word", "HAS/word", "LIVES-IN/word")
REL_FRAME = {"is-a": "IS-A/word", "has": "HAS/word", "lives-in": "LIVES-IN/word"}
DEFAULT_CFG = {"store": "episodic", "encoder": "frozen", "code": "dense", "consolidation": "offline",
               "engine": {"theta_novel": 3.9, "theta_margin": 0.5, "centering_warmup": 50}}  # fmt: skip


class Mind:
    def __init__(self, seed: int = 0, cfg: dict | None = None, D: int = 300, reader: Any = None) -> None:
        self.seed = seed
        self.reader = reader if reader is not None else Reader(D=D, seed=seed)
        self.cfg = SNIConfig.from_dict(cfg or DEFAULT_CFG)
        self.brain: Brain | None = None
        self.cues: dict[str, dict[str, float]] = {r: {} for r in REL_FRAME}
        self.facts: list[dict[str, Any]] = []  # confirmed / rejected judgements (for re-encoding)
        self.surprises: list[dict[str, Any]] = []
        self.pending: dict[str, Any] | None = None
        self.counts = {"plus": 0, "minus": 0, "proposals_made": 0, "proposals_right": 0}

    # ------------------------------------------------------------------------------------------
    # perception through the reader
    # ------------------------------------------------------------------------------------------
    def vec(self, form: str) -> np.ndarray | None:
        return self.reader.meaning(form)

    def ensure_brain(self) -> Brain:
        if self.brain is None:
            self.brain = Brain(self.cfg, frames=MIND_FRAMES, input_shape=(self.reader.D,),
                               seed=self.seed)  # fmt: skip
            if not getattr(self, "warm_forms", None):  # first experience, kept for re-encoding
                ids, _ = self.reader.meanings(min_n=3)
                rng = np.random.default_rng(self.seed)
                n0 = int(self.cfg.engine.centering_warmup)
                self.warm_forms = [self.reader.by_id[int(ids[i])].form for i in rng.permutation(len(ids))[:n0]]
            for f in self.warm_forms:
                v = self.vec(f)
                if v is not None:
                    self.brain.tick(v)  # unlabelled warm-up of perception centring
        return self.brain

    def reencode(self) -> dict[str, Any]:
        """After more reading the senses have changed: rebuild the concept memory by replaying
        every confirmed judgement through the new meaning vectors (offline replay)."""
        if self.brain is None:
            return {"replayed": 0}
        old, self.brain = self.facts, None
        self.facts = []
        b = self.ensure_brain()
        n = 0
        for f in old:
            if f["f"] < 0:
                continue
            if f["kind"] == "named" and self.vec(f["subject"]) is not None:
                self._teach_named(f["subject"], f["object"], f.get("teacher", "replay"))
                n += 1
            elif f["kind"] in REL_FRAME:
                self._teach_relation(f["subject"], f["kind"], f["object"], f.get("teacher", "replay"))
                n += 1
        b.sleep()
        return {"replayed": n}

    # ------------------------------------------------------------------------------------------
    # metacognition
    # ------------------------------------------------------------------------------------------
    def diagnose(self, form: str) -> dict[str, Any]:
        r = self.reader
        form = form.strip().lower()
        w = r.words.get(form)
        ref = r.wordlike_ref()
        out: dict[str, Any] = {"form": form, "signals": []}
        bits = r.letters.surprise(form, 1)
        out["letter_bits"] = round(bits, 2)
        out["letter_trace"] = r.letters.letter_bits(form)
        out["typical_bits"] = round(ref, 2)
        if w is None:
            similar = r.similar_forms(form)
            out["level"] = "form"
            out["similar_forms"] = [{"form": f, "overlap": round(j, 2)} for f, j in similar]
            if similar and similar[0][1] >= 0.5:
                out["wordlike"] = "variant"
                out["signals"].append({"kind": "form", "text": f"I have never read “{form}”. It looks like “{similar[0][0]}”.",
                                       "question": f"Is “{form}” a form of “{similar[0][0]}”, or a new word?"})  # fmt: skip
            elif bits <= ref + 2.5:
                out["wordlike"] = "plausible" if bits <= ref + 1.0 else "unusual"
                out["signals"].append({"kind": "form", "text": f"I have never read “{form}”, but its letters fit how words are spelled ({bits:.1f} bits per letter pair; most words I know are under {ref:.1f}).",
                                       "question": f"What is a “{form}”? Use it in a sentence?"})  # fmt: skip
            else:
                out["wordlike"] = "no"
                out["signals"].append({"kind": "form", "text": f"“{form}” does not look like a word: {bits:.1f} bits per letter pair, against under {ref:.1f} for words I know.",
                                       "question": "Is that really a word?"})  # fmt: skip
            return out
        out["reads"] = w.n
        out["first"] = w.first
        glue = w.id in r.glue()
        out["glue"] = glue
        if glue:
            out["level"] = "glue"
            out["signals"].append({"kind": "exposure", "text": f"“{form}” is everywhere ({w.n} times): it glues sentences together; it does not name a thing.",
                                   "question": None})  # fmt: skip
            return out
        m = self.vec(form)
        near = r.neighbours(m, 6, exclude=form)
        out["neighbours"] = [{"form": f, "sim": round(s, 3), "named": self._named(f)} for f, s in near]
        if w.n < 3:
            out["level"] = "exposure"
            out["signals"].append({"kind": "exposure", "text": f"I have read “{form}” only {w.n} time{'s' if w.n > 1 else ''}. Too little to know what it is like.",
                                   "question": f"Can you tell me what a “{form}” is?"})  # fmt: skip
        b = self.brain
        if b is not None:
            p = b.peek(m, "WHAT-IS")
            out["named"] = p["answer"]
            out["verdict"] = p["verdict"]
            out["confidence"] = round(float(p["confidence"]), 3)
            labels = [n["named"] for n in out["neighbours"] if n["named"]]
            if p["answer"] is None or p["verdict"] == "novel":
                out.setdefault("level", "meaning")
                like = ", ".join(f for f, _ in near[:3])
                out["signals"].append({"kind": "meaning", "text": f"I know what “{form}” is like ({like}), but I have no name for it.",
                                       "question": f"What is a “{form}”?"})  # fmt: skip
            elif p["verdict"] == "ambiguous" or len(set(labels[:4])) > 1:
                out.setdefault("level", "meaning")
                alts = sorted(set(labels[:4]) | {p["answer"]})
                out["signals"].append({"kind": "meaning", "text": f"I am torn about “{form}”: {' or '.join(alts)}.",
                                       "question": f"Is “{form}” a {p['answer']}?"})  # fmt: skip
            else:
                out.setdefault("level", "known")
        else:
            out.setdefault("level", "meaning")
            out["signals"].append({"kind": "meaning", "text": "I can tell what it is like, but nobody has taught me any names yet.",
                                   "question": f"What is a “{form}”?"})  # fmt: skip
        return out

    def _named(self, form: str) -> str | None:
        if self.brain is None:
            return None
        m = self.vec(form)
        if m is None:
            return None
        p = self.brain.peek(m, "WHAT-IS")
        return p["answer"] if p["verdict"] != "novel" else None

    def vote_name(self, m: np.ndarray, k: int = 10, exclude: str | None = None) -> tuple[str | None, float]:
        """Name by resemblance: the names it gives to the k words this one reads most like,
        weighted by similarity. (Post-hoc variant for fast mapping; see lex/results.)"""
        votes: dict[str, float] = {}
        for f, sim in self.reader.neighbours(m, k, exclude=exclude):
            n = self._named(f)
            if n:
                votes[n] = votes.get(n, 0.0) + max(sim, 0.0)
        if not votes:
            return None, 0.0
        best = max(votes, key=votes.get)
        return best, round(votes[best] / (sum(votes.values()) + 1e-12), 3)

    def read_probe(self, sentence: str, learn: bool = False) -> dict[str, Any]:
        """Read one sentence and say what was understood, word by word. Unknown words are
        fast-mapped: a one-shot meaning from the known words around them."""
        r = self.reader
        toks = r.tokenize(sentence)
        toks = toks[0] if toks else []
        rep = r.read_sentence(toks, learn=False)
        glue = r.glue()
        for i, t in enumerate(rep):
            w = r.words.get(t["form"])
            t["glue"] = bool(w is not None and w.id in glue)
            t["reads"] = 0 if w is None else w.n
            if w is None or w.n < 3:
                ctx = r.context_from(toks, i)
                if w is not None:
                    ctx = ctx + w.ctx
                if np.linalg.norm(ctx) > 0:
                    m = r.meaning_of_ctx(ctx)
                    near = r.neighbours(m, 5, exclude=t["form"])
                    t["guess_like"] = [f for f, _ in near]
                    if self.brain is not None:
                        p = self.brain.peek(m, "WHAT-IS")
                        t["guess_name"] = p["answer"]
                        t["guess_verdict"] = p["verdict"]
                        t["guess_vote"], t["vote_share"] = self.vote_name(m, exclude=t["form"])
            if t.get("next_bits") is not None and t["next_bits"] > 9 and t["known"] and not t["glue"]:
                t["surprising"] = True
        if learn:
            r.read_sentence(toks)
        flagged = [t for t in rep if t.get("surprising")]
        if flagged:
            self.surprises.append({"sentence": sentence, "words": [t["form"] for t in flagged]})
        return {"tokens": rep, "learned": learn}

    # ------------------------------------------------------------------------------------------
    # teaching (Brain protocol)
    # ------------------------------------------------------------------------------------------
    def ask(self, form: str, frame: str = "WHAT-IS") -> dict[str, Any]:
        b = self.ensure_brain()
        fr = FRAMES[frame]
        if fr.subject == "word":
            raw: Any = form
        else:
            raw = self.vec(form)
            if raw is None:
                return {"kind": "unknown-form", "diagnosis": self.diagnose(form)}
        act = b.query(raw, frame)
        self.pending = {"form": form, "frame": frame, "act": act}
        return self._act(act, form)

    def _act(self, act: Any, form: str) -> dict[str, Any]:
        b = self.brain
        tr = []
        for e, c in act.trace:
            E = b.edges
            tr.append({"src": self._lbl(int(E.src[e])), "rel": E.types[E.rtype[e]],
                       "dst": self._lbl(int(E.dst[e])), "w": round(float(E.w[e]), 3)})  # fmt: skip
        return {"kind": act.kind, "answer": act.answer, "question": act.question,
                "verdict": act.verdict, "confidence": round(float(act.confidence), 3),
                "about": act.meta.get("about"), "path": list(act.meta.get("path", ())),
                "needs": act.meta.get("needs"), "trace": tr, "form": form}  # fmt: skip

    def _lbl(self, u: int) -> str:
        b = self.brain
        m = b.units.meta[u]
        if m.kind == "word":
            return str(m.label)
        raw = b.shown.get(u)
        if raw is not None:
            v = np.asarray(raw)
            best = self.reader.neighbours(v / (np.linalg.norm(v) + 1e-12), 1)
            return f"“{best[0][0]}”" if best else f"#{u}"
        return f"#{u}"

    def hear(self, word: str) -> dict[str, Any]:
        act = self.brain.hear(word.strip().lower())
        self.pending["act"] = act
        return self._act(act, self.pending["form"])

    def judge(self, f: int, teacher: str = "you") -> dict[str, Any]:
        p = self.pending
        act = p["act"]
        rep = self.brain.feedback(int(f), teacher)
        self.counts["plus" if f > 0 else "minus"] += 1
        rel = act.meta.get("path", ("named",))[-1] if act.meta.get("path") else "named"
        kind = "named" if FRAMES[p["frame"]].subject == "percept" and rel == "named" else rel
        subj = p["form"] if kind == "named" or FRAMES[p["frame"]].subject == "word" else (act.meta.get("about") or p["form"])
        self.facts.append({"kind": kind, "subject": subj, "object": act.answer, "f": int(f), "teacher": teacher})
        if kind in REL_FRAME and act.answer:
            self._learn_cues(subj, kind, act.answer, float(rep["m_t"]))
        if f < 0 and act.kind in ("answer", "confirm") and act.confidence > 0.6:
            self.surprises.append({"sentence": f"I was sure “{p['form']}” → {act.answer}, and you said no.", "words": [p["form"]]})
        self.pending = None
        return {"m_t": round(float(rep["m_t"]), 3), "formed": len(rep["formed"]), "surprise": round(float(rep["gamma"]), 3)}

    def _teach_named(self, form: str, name: str, teacher: str) -> None:
        a = self.ask(form, "WHAT-IS")
        if a["kind"] == "ask":
            self.hear(name)
            self.judge(1, teacher)
        elif a["kind"] in ("answer", "confirm"):
            self.judge(1 if a["answer"] == name else -1, teacher)

    def _teach_relation(self, subj: str, rel: str, obj: str, teacher: str) -> None:
        a = self.ask(subj, REL_FRAME[rel])
        if a["kind"] == "ask" and a.get("needs") != "example":
            self.hear(obj)
            self.judge(1, teacher)
        elif a["kind"] in ("answer", "confirm"):
            self.judge(1 if a["answer"] == obj else -1, teacher)
        else:
            self.pending = None

    # ------------------------------------------------------------------------------------------
    # connections the Mind proposes itself
    # ------------------------------------------------------------------------------------------
    def _patterns(self, a: str, b: str) -> dict[str, float]:
        r = self.reader
        wa, wb = r.words.get(a), r.words.get(b)
        if wa is None or wb is None:
            return {}
        return r.assoc.get((wa.id, wb.id), {})

    @staticmethod
    def _features(pats: dict[str, float]) -> dict[str, float]:
        """Cue features of a pair: each in-between pattern, and each word stem in it (first 4
        letters, so 'live'/'lives'/'living' share a feature), as shares of the pair's readings."""
        tot = sum(pats.values()) or 1.0
        f: dict[str, float] = {}
        for p, c in pats.items():
            f["=" + p] = f.get("=" + p, 0.0) + c / tot
            for t in set(p.split()):
                f[t[:4]] = f.get(t[:4], 0.0) + c / tot
        return f

    def _learn_cues(self, subj: str, rel: str, obj: str, m_t: float) -> None:
        cue = self.cues[rel]
        for k, v in self._features(self._patterns(subj, obj)).items():
            cue[k] = cue.get(k, 0.0) + update_relation_cue(v, m_t, cue.get(k, 0.0))

    def propose(self, k: int = 8) -> list[dict[str, Any]]:
        out: list[dict[str, Any]] = []
        b = self.brain
        r = self.reader
        if b is None:
            return out
        judged = {(f["kind"], f["subject"], f["object"]) for f in self.facts}
        named_subjects = {f["subject"] for f in self.facts if f["kind"] == "named"}
        # (1) kind: well-read words the Mind thinks it can name, by resemblance
        ids, M = r.meanings(min_n=4)
        cands = []
        for i, wid in enumerate(ids):
            form = r.by_id[int(wid)].form
            if form in named_subjects:
                continue
            p = b.peek(M[i], "WHAT-IS")
            if p["answer"] and p["verdict"] in ("known", "ambiguous") and ("named", form, p["answer"]) not in judged:
                near = [f for f, _ in r.neighbours(M[i], 4, exclude=form)]
                cands.append((p["confidence"] * (1.0 if p["verdict"] == "known" else 0.6), form, p["answer"], near))
        for conf, form, ans, near in sorted(cands, reverse=True)[: k // 2 + 1]:
            out.append({"type": "kind", "subject": form, "rel": "is a", "object": ans, "score": round(conf, 3),
                        "why": f"“{form}” reads like " + ", ".join(near[:3])})  # fmt: skip
        # (2) relations: word pairs whose in-between patterns match a learned relation cue
        words = [m.label for m in b.units.meta if m.kind == "word" and m.alive]
        rc = []
        for rel, cue in self.cues.items():
            good = {p: w for p, w in cue.items() if w > 0}
            if not good:
                continue
            for a in words:
                wa = r.words.get(a)
                if wa is None:
                    continue
                for (x, y), pats in r.assoc.items():
                    if x != wa.id:
                        continue
                    obj = r.by_id[y].form
                    if (rel, a, obj) in judged or obj == a:
                        continue
                    tot = sum(pats.values())
                    feats = self._features(pats)
                    s = sum(v * good.get(k, 0.0) for k, v in feats.items()) * math.log1p(tot)
                    if s > 0.3:
                        best = max(pats, key=lambda p: sum(good.get(k, 0.0) for k in ["=" + p] + [t[:4] for t in p.split()]))
                        rc.append((s, a, rel, obj, best, int(pats[best])))
        for s, a, rel, obj, pat, n in sorted(rc, reverse=True)[: k // 2]:
            out.append({"type": "relation", "subject": a, "rel": rel, "object": obj, "score": round(s, 3),
                        "why": f"I read “{a} {pat} {obj}” ({n}×), and words like “{pat}” went with “{rel}” before"})  # fmt: skip
        return out

    def accept(self, proposal: dict[str, Any], f: int, teacher: str = "you") -> dict[str, Any]:
        """The teacher's ±1 on a proposal the Mind made. The proposed word is the Mind's own."""
        self.counts["proposals_made"] += 1
        self.counts["proposals_right"] += int(f > 0)
        if proposal["type"] == "kind":
            a = self.ask(proposal["subject"], "WHAT-IS")
            if a["kind"] == "ask":
                self.hear(proposal["object"])  # self-proposal: the Mind's own candidate
            return self.judge(f, teacher)
        a = self.ask(proposal["subject"], REL_FRAME[proposal["rel"]])
        if a["kind"] == "ask" and a.get("needs") != "example":
            self.hear(proposal["object"])
            return self.judge(f, teacher)
        if a["kind"] in ("answer", "confirm"):
            if a["answer"] == proposal["object"]:
                return self.judge(f, teacher)
            self.pending = None
            self._learn_cues(proposal["subject"], proposal["rel"], proposal["object"], float(f))
            return {"note": "brain already holds another answer on that path"}
        self.pending = None
        return {"note": "subject not known as a word yet"}

lex/lab.py:
"""SNI Reader — JSON bridge between the web page and the letters-up Mind (runs under Pyodide).

Scripted teachers (autopilot) read ``gold.json`` to give their ±1 or to answer the Mind's
questions; the Mind never reads it. ``exam`` is a pure read-out.
"""

from __future__ import annotations

import json
import time
from pathlib import Path
from typing import Any

import numpy as np

from lex.layout import tsne
from lex.mind import REL_FRAME, Mind

DATA = Path(__file__).parent / "data"
SOURCES = {"grammar": "grammar_corpus.txt", "books": "books_corpus.txt"}
TEACHERS = ("T1", "T2", "T3")


class Lab:
    def __init__(self, seed: int = 0, snapshot: str | None = None) -> None:
        self.grown = snapshot is not None
        reader = None
        if self.grown:
            from lex.grown import GrownReader

            reader = GrownReader(snapshot)
        self.mind = Mind(seed, reader=reader)
        from lex.facts import FactMemory

        self.facts = FactMemory(self.mind.reader)
        self.fact_props: list[dict[str, Any]] = []
        self.gold = json.loads((DATA / "gold.json").read_text())
        self.kind = {w: c for c, ws in self.gold["categories"].items() for w in ws}
        self.text: dict[str, list[list[str]]] = {}
        self.cursor = {k: 0 for k in SOURCES}
        self.proposals: list[dict[str, Any]] = []
        self.layout: dict[str, np.ndarray] = {}
        self.auto_i = 0
        self.born_in: dict[str, set[str]] = {k: set() for k in SOURCES}
        self.log: list[dict[str, Any]] = []

    def _sentences(self, source: str) -> list[list[str]]:
        if source not in self.text:
            self.text[source] = self.mind.reader.tokenize((DATA / SOURCES[source]).read_text())
        return self.text[source]

    # ------------------------------------------------------------------------------------------
    def read(self, source: str = "grammar", n: int = 400) -> dict[str, Any]:
        t0 = time.perf_counter()
        r = self.mind.reader
        sents = self._sentences(source)
        a = self.cursor[source]
        b = min(len(sents), a + int(n))
        born0 = len(r.by_id)
        for toks in sents[a:b]:
            r.read_sentence(toks, report=False)
        self.cursor[source] = b
        self.born_in[source].update(w.form for w in r.by_id[born0:])
        sample = []
        glue = r.glue()
        for toks in sents[max(a, b - 4) : b]:
            sample.append([{"f": t, "born": r.words[t].born >= 0 and r.words[t].id >= born0,
                            "glue": r.words[t].id in glue} for t in toks])  # fmt: skip
        return {"read": b - a, "done": b >= len(sents), "position": b, "total": len(sents),
                "new_words": [w.form for w in r.by_id[born0:]][:40], "n_new": len(r.by_id) - born0,
                "sample": sample, "ms": round((time.perf_counter() - t0) * 1e3), "stats": self.stats()}  # fmt: skip

    def stats(self) -> dict[str, Any]:
        r, m = self.mind.reader, self.mind
        b = m.brain
        named = sum(1 for f in m.facts if f["kind"] == "named" and f["f"] > 0)
        rels = sum(1 for f in m.facts if f["kind"] in REL_FRAME and f["f"] > 0)
        return {
            "letters": len(r.letters.next), "words": len(r.by_id), "tokens": r.tokens,
            "sentences": r.sentences, "glue": len(r.glue()),
            "assoc": len(r.assoc), "names_taught": named, "relations": rels,
            "concepts": 0 if b is None else sum(1 for u in b.units.meta if u.kind == "word" and u.alive),
            "engrams": 0 if b is None else sum(1 for u in b.units.meta if u.kind == "percept" and u.alive),
            "plus": m.counts["plus"], "minus": m.counts["minus"],
            "proposals_made": m.counts["proposals_made"], "proposals_right": m.counts["proposals_right"],
            "cursor": self.cursor, "grown": self.grown,
            "corpus": getattr(r, "meta", {}).get("corpus"), **self.facts.stats(),
        }  # fmt: skip

    def map(self, n: int = 320, iters: int = 160) -> dict[str, Any]:
        """The Mind's own map of meaning: t-SNE of its own vectors (display only)."""
        r = self.mind.reader
        ids, M = r.meanings(min_n=3)
        if ids.size < 5:
            return {"points": []}
        byn = sorted(range(len(ids)), key=lambda i: -r.by_id[int(ids[i])].n)
        first = self.born_in["grammar"]
        if self.grown:  # the taxonomy's words, every taught word, then the most-read words
            taught = {f["subject"] for f in self.mind.facts}
            want = set(self.kind) | taught
            first = {r.by_id[int(ids[i])].form for i in byn if r.by_id[int(ids[i])].form in want}
        if first and len(first) < len(ids):  # keep the taxonomy visible among everything else read
            prim = [i for i in byn if r.by_id[int(ids[i])].form in first]
            pick = np.random.default_rng(0).permutation(len(prim))[: int(n * (0.8 if self.grown else 0.7))]
            a = [prim[k] for k in sorted(pick)]  # an even sample of the primer's words
            order = a + [i for i in byn if r.by_id[int(ids[i])].form not in first][: n - len(a)]
        else:
            order = byn[:n]
        forms = [r.by_id[int(ids[i])].form for i in order]
        X = M[order]
        init = None
        if all(f in self.layout for f in forms[: max(1, len(forms) // 2)]):
            rng = np.random.default_rng(0)
            init = np.stack([self.layout.get(f, rng.normal(0, 1e-2, 2)) for f in forms])
        Y = tsne(X, init=init, iters=iters if init is None else max(60, iters // 3))
        for f, y in zip(forms, Y):
            self.layout[f] = y
        lo, hi = np.percentile(Y, 2, axis=0), np.percentile(Y, 98, axis=0)
        Z = np.clip((Y - lo) / np.maximum(hi - lo, 1e-9), -0.03, 1.03)
        pts = []
        b = self.mind.brain
        for i, f in enumerate(forms):
            named = None
            if b is not None:
                p = b.peek(X[i], "WHAT-IS")
                named = p["answer"] if p["verdict"] != "novel" else None
            pts.append({"f": f, "x": round(float(Z[i, 0]), 4), "y": round(float(Z[i, 1]), 4),
                        "n": r.by_id[int(ids[order[i]])].n, "named": named, "gold": self.kind.get(f)})  # fmt: skip
        taught = {fa["subject"] for fa in self.mind.facts if fa["kind"] == "named" and fa["f"] > 0}
        for p in pts:
            p["taught"] = p["f"] in taught
        return {"points": pts}

    # ------------------------------------------------------------------------------------------
    def diagnose(self, word: str) -> dict[str, Any]:
        return self.mind.diagnose(word)

    def probe(self, sentence: str, learn: bool = False) -> dict[str, Any]:
        return self.mind.read_probe(sentence, learn)

    def ask(self, word: str, frame: str = "WHAT-IS") -> dict[str, Any]:
        out = self.mind.ask(word.strip().lower(), frame)
        out["diagnosis"] = self.mind.diagnose(word) if frame == "WHAT-IS" else None
        return out

    def hear(self, word: str) -> dict[str, Any]:
        return self.mind.hear(word)

    def judge(self, f: int) -> dict[str, Any]:
        return self.mind.judge(int(f), "you")

    def propose(self, k: int = 8) -> dict[str, Any]:
        self.proposals = self.mind.propose(k)
        for p in self.proposals:
            if p["type"] == "kind":
                p["gold_ok"] = self.kind.get(p["subject"]) == p["object"]
            else:
                key = {"is-a": "is_a", "has": "has", "lives-in": "lives_in"}[p["rel"]]
                p["gold_ok"] = self.gold["facts"].get(key, {}).get(p["subject"]) == p["object"]
            p["score"] = float(p["score"])
        return {"proposals": self.proposals}

    def accept(self, i: int, f: int) -> dict[str, Any]:
        p = self.proposals[int(i)]
        out = self.mind.accept(p, int(f), "you")
        self.proposals.pop(int(i))
        return {"result": out, "stats": self.stats()}

    # ------------------------------------------------------------------------------------------
    def autoteach(self, per_category: int = 2) -> dict[str, Any]:
        """Three scripted teachers name `per_category` training words of every category."""
        m = self.mind
        m.ensure_brain()
        log = []
        for c, ws in self.gold["train_words"].items():
            done = 0
            for w in ws:
                if done >= per_category:
                    break
                if m.vec(w) is None:
                    continue
                t = TEACHERS[self.auto_i % 3]
                self.auto_i += 1
                m._teach_named(w, c, t)
                log.append({"word": w, "name": c, "teacher": t})
                done += 1
        return {"log": log, "stats": self.stats()}

    def teach_fact(self, subject: str = "fish", rel: str = "lives-in", obj: str = "water") -> dict[str, Any]:
        m = self.mind
        m.ensure_brain()
        for t in TEACHERS[:2]:
            m._teach_relation(subject, rel, obj, t)
        return {"stats": self.stats()}

    def auto_judge(self, rounds: int = 1) -> dict[str, Any]:
        """Scripted teachers judge the Mind's current proposals by the ground truth."""
        out = []
        for _ in range(int(rounds)):
            props = self.propose(10)["proposals"]
            if not props:
                break
            while self.proposals:
                p = self.proposals[0]
                f = 1 if p["gold_ok"] else -1
                t = TEACHERS[self.auto_i % 3]
                self.auto_i += 1
                self.mind.accept(p, f, t)
                out.append({**{k: p[k] for k in ("type", "subject", "rel", "object")}, "f": f})
                self.proposals.pop(0)
        return {"judged": out, "stats": self.stats()}

    def exam(self) -> dict[str, Any]:
        m = self.mind
        rows, novel = [], []
        b = m.brain
        if b is not None:
            for c, ws in self.gold["heldout_words"].items():
                for w in ws:
                    v = m.vec(w)
                    if v is None:
                        continue
                    p = b.peek(v, "WHAT-IS")
                    rows.append({"word": w, "truth": c, "answer": p["answer"], "verdict": p["verdict"],
                                 "ok": p["answer"] == c, "reads": m.reader.words[w].n})  # fmt: skip
        forms = []
        for w in self.gold["nonce"][:10]:
            d = m.diagnose(w)
            forms.append({"word": w, "type": "made-up word", "level": d["level"], "wordlike": d.get("wordlike")})
        for w, t in list(self.gold["misspellings"].items())[:6]:
            d = m.diagnose(w)
            forms.append({"word": w, "type": f"misspelling of {t}", "level": d["level"], "wordlike": d.get("wordlike"),
                          "looks_like": (d.get("similar_forms") or [{}])[0].get("form")})  # fmt: skip
        for w in ("xqzt", "bcdfg", "qqqq"):
            d = m.diagnose(w)
            forms.append({"word": w, "type": "letter noise", "level": d["level"], "wordlike": d.get("wordlike")})
        n = max(len(rows), 1)
        return {"rows": rows, "accuracy": sum(r["ok"] for r in rows) / n,
                "asks": sum(r["verdict"] == "novel" for r in rows) / n,
                "precision": (sum(r["ok"] for r in rows if r["verdict"] != "novel") /
                              max(1, sum(r["verdict"] != "novel" for r in rows))),
                "forms": forms}  # fmt: skip

    # --- facts between words -------------------------------------------------------------------
    def ask_link(self, a: str, b: str) -> dict[str, Any]:
        return self.facts.ask_link(a.strip().lower(), b.strip().lower())

    def hear_link(self, rel: str) -> dict[str, Any]:
        return self.facts.hear_link(rel)

    def judge_link(self, f: int) -> dict[str, Any]:
        out = self.facts.judge_link(int(f), "you")
        out["stats"] = self.stats()
        return out

    def propose_links(self, k: int = 8) -> dict[str, Any]:
        self.fact_props = self.facts.propose(k)
        return {"proposals": self.fact_props, "conflicts": self.facts.conflicts()}

    def accept_link(self, i: int, f: int) -> dict[str, Any]:
        p = self.fact_props.pop(int(i))
        self.facts.propose_own(p["subject"], p["rel"], p["object"])
        out = self.facts.judge_link(int(f), "you")
        self.mind.counts["proposals_made"] += 1
        self.mind.counts["proposals_right"] += int(f > 0)
        out["stats"] = self.stats()
        return out

    def facts_of(self, word: str) -> list[dict[str, Any]]:
        return self.facts.query(word.strip().lower())

    def reencode(self) -> dict[str, Any]:
        return self.mind.reencode()

    def sleep(self) -> dict[str, Any]:
        b = self.mind.ensure_brain()
        return {k: int(v) for k, v in (b.sleep() or {}).items()}

    def audit(self) -> dict[str, Any]:
        from sni.locality_audit import audit_all

        rep = audit_all(("sni.plasticity", "sni.perception", "lex.plasticity"))
        return {"functions": sorted(rep), "violations": {k: v for k, v in rep.items() if v},
                "clean": sum(1 for v in rep.values() if not v), "total": len(rep)}  # fmt: skip

    def reason(self, word: str) -> list[dict[str, Any]]:
        """Read-only multi-hop answers for a word (no state touched): IS-A, HAS, LIVES-IN."""
        from sni.frames import FRAMES
        from sni.routing import answer_trace

        b, v = self.mind.brain, self.mind.vec(word)
        if b is None or v is None:
            return []
        out = []
        for fr in ("IS-A", "IS-A-2", "HAS", "LIVES-IN"):
            inf = b._infer(v, FRAMES[fr])
            ans = int(inf["answer"])
            if ans < 0 or inf["verdict"] == "novel":
                out.append({"frame": fr, "answer": None})
                continue
            tr = answer_trace(inf["spread"], b.edges, ans)
            E = b.edges
            out.append({"frame": fr, "answer": b.label(ans), "confidence": round(float(inf["confidence"]), 3),
                        "path": [[self.mind._lbl(int(E.src[e])), E.types[E.rtype[e]], self.mind._lbl(int(E.dst[e]))]
                                 for e, _ in tr]})  # fmt: skip
        return out

    def explain_word(self, word: str) -> dict[str, Any]:
        """Everything the Mind holds about a word: letters, reads, neighbours, name, edges."""
        d = self.mind.diagnose(word)
        r = self.mind.reader
        w = r.words.get(word)
        if w is not None:
            nx = r.nexts.get(w.id, {})
            d["next_words"] = [r.by_id[j].form for j, _ in sorted(nx.items(), key=lambda x: -x[1])[:6]]
            pairs = [(r.by_id[y].form, sum(p.values()), max(p, key=p.get)) for (x, y), p in r.assoc.items() if x == w.id]
            d["associations"] = [{"form": f, "n": int(n), "via": via} for f, n, via in sorted(pairs, key=lambda x: -x[1])[:6]]
            d["reasoning"] = self.reason(word)
        return d


LAB: Lab | None = None


def call(method: str, args_json: str = "{}") -> str:
    global LAB
    args = json.loads(args_json or "{}")
    try:
        if method == "reset" or LAB is None:
            LAB = Lab(int(args.get("seed", 0)), args.get("snapshot"))
            if method == "reset":
                return json.dumps({"ok": True, "result": LAB.stats()})
        return json.dumps({"ok": True, "result": getattr(LAB, method)(**args)}, default=float)
    except Exception as exc:  # noqa: BLE001 - surfaced to the page
        return json.dumps({"ok": False, "error": f"{type(exc).__name__}: {exc}"})

lex/facts.py:
"""Facts between words the Mind has read, e.g. "paris —capital-of→ france".

Same rules as the concept engine (Decision Log 2026-11-06, decision 3): a fact enters memory only
as a proposition the Mind made, judged ±1 by a teacher. A relation NAME enters only as the answer
to the Mind's own question ("how is 'paris' connected to 'france'?"), and forms nothing until a
+1. Edge weights change through the audited ``sni.plasticity.update_edge_named``; relation cues
(the words read between two words) through ``lex.plasticity.update_relation_cue``.

After one confirmed example the Mind proposes others itself, ranked by
  cue match (were these two words read with the same in-between words?)
× type match (do they resemble the confirmed subject and object?)
which is DIPRE/Snowball-style bootstrapping, gated by the teacher at every step (the known failure
of bootstrapping is semantic drift; every proposal is judged before it can teach the cues).
"""

from __future__ import annotations

import math
from dataclasses import dataclass, field
from typing import Any

import numpy as np

from lex.plasticity import update_relation_cue
from sni.plasticity import update_edge_named


@dataclass
class FactEdge:
    w: float = 0.0
    support: dict[str, float] = field(default_factory=dict)
    contra: float = 0.0
    consolidated: bool = False


class FactMemory:
    def __init__(self, reader: Any, maturity_k: int = 2) -> None:
        self.r = reader
        self.k = maturity_k
        self.edges: dict[tuple[str, str, str], FactEdge] = {}
        self.cues: dict[str, dict[str, float]] = {}
        self.pos: dict[str, list[tuple[str, str]]] = {}
        self.neg: dict[str, list[tuple[str, str]]] = {}
        self.pending: dict[str, Any] | None = None
        self._index: dict[str, list[tuple[int, int]]] | None = None

    # --- evidence from reading -------------------------------------------------------------------
    def patterns(self, a: str, b: str) -> dict[str, float]:
        wa, wb = self.r.words.get(a), self.r.words.get(b)
        if wa is None or wb is None:
            return {}
        return self.r.assoc.get((wa.id, wb.id), {})

    @staticmethod
    def features(pats: dict[str, float]) -> dict[str, float]:
        tot = sum(pats.values()) or 1.0
        f: dict[str, float] = {}
        for p, c in pats.items():
            f["=" + p] = f.get("=" + p, 0.0) + c / tot
            for t in set(p.split()):
                f[t[:5]] = f.get(t[:5], 0.0) + 0.5 * c / tot
        return f

    # --- the protocol: the Mind asks, the teacher answers, the Mind proposes, the teacher judges ---
    def ask_link(self, a: str, b: str) -> dict[str, Any]:
        pats = self.patterns(a, b)
        known = [(r, e) for (x, r, y), e in self.edges.items() if x == a and y == b and e.w > 0]
        if known:
            r, e = max(known, key=lambda t: t[1].w)
            return {"kind": "answer", "a": a, "b": b, "rel": r, "w": round(e.w, 3),
                    "consolidated": e.consolidated}  # fmt: skip
        guess = self._best_rel(a, b)
        self.pending = {"a": a, "b": b, "stage": "asked"}
        top = sorted(pats.items(), key=lambda x: -x[1])[:4]
        return {"kind": "ask", "a": a, "b": b, "question": f"How is “{a}” connected to “{b}”?",
                "read_between": [{"pattern": p, "n": int(c)} for p, c in top], "guess": guess}  # fmt: skip

    def hear_link(self, rel: str) -> dict[str, Any]:
        if not self.pending:
            raise ValueError("hear_link() needs an open question from the Mind")
        rel = "-".join(rel.strip().lower().split())
        self.pending.update(rel=rel, stage="proposed")
        return {"kind": "proposal", "text": f"So “{self.pending['a']}” {rel} “{self.pending['b']}”?",
                **{k: self.pending[k] for k in ("a", "rel", "b")}}  # fmt: skip

    def propose_own(self, a: str, rel: str, b: str) -> None:
        """The Mind's own candidate, put up for a teacher's ±1 (relation name already known)."""
        self.pending = {"a": a, "b": b, "rel": rel, "stage": "proposed"}

    def judge_link(self, f: int, teacher: str = "you") -> dict[str, Any]:
        p = self.pending
        if not p or p.get("stage") != "proposed":
            raise ValueError("no proposed fact to judge")
        a, rel, b = p["a"], p["rel"], p["b"]
        surprise = 1.0 - self.score(a, rel, b)[0] if rel in self.cues else 0.5
        m_t = float(f) * (0.5 + 0.5 * surprise)  # surprising verdicts teach more
        key = (a, rel, b)
        e = self.edges.get(key)
        formed = False
        if e is None and f > 0:
            e = self.edges[key] = FactEdge()
            formed = True
        if e is not None:
            e.w = max(0.0, e.w + update_edge_named(m_t, True, eta=0.5))
            if f > 0:
                e.support[teacher] = e.support.get(teacher, 0.0) + 1.0
            else:
                e.contra += 1.0
            e.consolidated = len(e.support) >= self.k and sum(e.support.values()) > e.contra
        cue = self.cues.setdefault(rel, {})
        for k, v in self.features(self.patterns(a, b)).items():
            cue[k] = cue.get(k, 0.0) + update_relation_cue(v, m_t, cue.get(k, 0.0))
        (self.pos if f > 0 else self.neg).setdefault(rel, []).append((a, b))
        self.pending = None
        return {"formed": formed, "m_t": round(m_t, 3), "fact": {"a": a, "rel": rel, "b": b},
                "w": round(e.w, 3) if e else 0.0, "consolidated": bool(e and e.consolidated)}  # fmt: skip

    # --- the Mind's own proposals ----------------------------------------------------------------
    def _sim(self, x: str, y: str) -> float:
        mx, my = self.r.meaning(x), self.r.meaning(y)
        return 0.0 if mx is None or my is None else float(mx @ my)

    def score(self, a: str, rel: str, b: str) -> tuple[float, float, float]:
        cue = {k: v for k, v in self.cues.get(rel, {}).items() if v > 0}
        feats = self.features(self.patterns(a, b))
        cue_s = sum(v * cue.get(k, 0.0) for k, v in feats.items())
        ex = self.pos.get(rel, [])
        type_s = max((max(0.0, self._sim(a, x)) * max(0.0, self._sim(b, y)) for x, y in ex), default=0.0)
        n = sum(self.patterns(a, b).values())
        s = math.tanh(cue_s) * math.sqrt(type_s) * min(1.0, math.log1p(n) / 2)
        return s, cue_s, type_s

    def _best_rel(self, a: str, b: str) -> str | None:
        best = max(((self.score(a, r, b)[0], r) for r in self.cues), default=(0.0, None))
        return best[1] if best[0] > 0.15 else None

    def _candidates(self, rel: str) -> list[tuple[int, int]]:
        if self._index is None:
            self._index = {}
            for key, pats in self.r.assoc.items():
                for p in pats:
                    self._index.setdefault("=" + p, []).append(key)
        out: set[tuple[int, int]] = set()
        for k, v in sorted(self.cues.get(rel, {}).items(), key=lambda x: -x[1])[:6]:
            if v > 0 and k.startswith("="):
                out.update(self._index.get(k, [])[:4000])
        return list(out)

    def propose(self, k: int = 8) -> list[dict[str, Any]]:
        judged = {(a, r, b) for r in self.pos for a, b in self.pos[r]} | \
                 {(a, r, b) for r in self.neg for a, b in self.neg[r]}  # fmt: skip
        props = []
        for rel in self.cues:
            if not self.pos.get(rel):
                continue
            for x, y in self._candidates(rel):
                a, b = self.r.by_id[x].form, self.r.by_id[y].form
                if (a, rel, b) in judged or a == b:
                    continue
                s, cs, ts = self.score(a, rel, b)
                if s > 0.12:
                    pats = self.patterns(a, b)
                    best = max(pats, key=pats.get)
                    props.append({"type": "fact", "subject": a, "rel": rel, "object": b, "score": round(s, 3),
                                  "why": f"read “{a} {best} {b}” ({int(pats[best])}×); "
                                         f"{a}/{b} resemble {self.pos[rel][-1][0]}/{self.pos[rel][-1][1]}"})  # fmt: skip
        props.sort(key=lambda p: -p["score"])
        return props[:k]

    def query(self, a: str, rel: str | None = None) -> list[dict[str, Any]]:
        out = []
        for (x, r, y), e in self.edges.items():
            if e.w > 0 and (x == a or y == a) and (rel is None or r == rel):
                out.append({"a": x, "rel": r, "b": y, "w": round(e.w, 3), "consolidated": e.consolidated})
        return sorted(out, key=lambda d: -d["w"])

    def conflicts(self) -> list[dict[str, Any]]:
        """A relation whose confirmed examples are all one-to-one, yet one subject now has two
        confirmed objects: a contradiction the Mind should raise."""
        out = []
        for rel, ex in self.pos.items():
            objs: dict[str, set[str]] = {}
            for a, b in ex:
                objs.setdefault(a, set()).add(b)
            multi = {a: sorted(bs) for a, bs in objs.items() if len(bs) > 1}
            if multi and sum(len(v) for v in objs.values()) > len(multi) + 2:
                for a, bs in multi.items():
                    out.append({"rel": rel, "subject": a, "objects": bs,
                                "text": f"I hold two answers for “{a}” {rel}: {', '.join(bs)}. Which is right?"})  # fmt: skip
        return out

    def stats(self) -> dict[str, int]:
        return {"facts": sum(1 for e in self.edges.values() if e.w > 0),
                "consolidated_facts": sum(1 for e in self.edges.values() if e.consolidated),
                "relations": len([r for r in self.cues if self.pos.get(r)])}  # fmt: skip

lex/grown.py:
"""A grown reader: the state of a Reader that has already read a large corpus (text8 / Wikipedia),
loaded from a snapshot written by ``lex/big`` (meaning vectors, letter engrams, next-word edges,
between-word patterns). Same interface as ``lex.reader.Reader`` so ``lex.mind.Mind`` runs on it
unchanged. Read-only knowledge, plus new words learned at runtime from one sentence (fast mapping):
their meaning is formed from the meanings of the words around them and stored as a new engram.
"""

from __future__ import annotations

import json
import math
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import numpy as np

from lex.reader import TOKEN, LetterMemory, trigrams


@dataclass
class GrownWord:
    id: int
    form: str
    n: int
    first: str = ""
    born: int = 0


class GrownReader:
    def __init__(self, root: str | Path) -> None:
        root = Path(root)
        self.meta = json.loads((root / "meta.json").read_text())
        forms = json.loads((root / "words.json").read_text())
        counts = json.loads((root / "counts.json").read_text())
        self.D = int(self.meta["D"])
        q = np.frombuffer((root / "meaning.i8").read_bytes(), dtype=np.int8).reshape(len(forms), self.D)
        s = np.frombuffer((root / "meaning.scale.f32").read_bytes(), dtype="<f4")
        M = q.astype(np.float64) * s[:, None]
        M /= np.linalg.norm(M, axis=1, keepdims=True) + 1e-12
        self.M = M
        self.by_id = [GrownWord(i, f, int(c)) for i, (f, c) in enumerate(zip(forms, counts))]
        self.words = {w.form: w for w in self.by_id}
        self.tokens = int(self.meta["tokens"])
        self.sentences = 0
        self.letters = LetterMemory()
        for ctx, d in json.loads((root / "letters.json").read_text()).items():
            self.letters.next[ctx] = {k: float(v) for k, v in d.items()}
            self.letters.total[ctx] = float(sum(d.values()))
        self.nexts: dict[int, dict[int, float]] = {}
        nx = root / "next.json"
        if nx.exists():
            for a, lst in json.loads(nx.read_text()).items():
                if a in self.words:
                    self.nexts[self.words[a].id] = {self.words[b].id: float(c) for b, c in lst if b in self.words}
        self.assoc: dict[tuple[int, int], dict[str, float]] = {}
        pf = root / "pairs.json"
        if pf.exists():
            for key, pats in json.loads(pf.read_text()).items():
                a, b = key.split("\t")
                if a in self.words and b in self.words:
                    self.assoc[(self.words[a].id, self.words[b].id)] = {p: float(c) for p, c in pats.items()}
        self._glue = {self.words[g].id for g in self.meta.get("glue", []) if g in self.words}
        self._new = 0
        self._tri: list[set[str]] | None = None

    # --- Reader interface ---------------------------------------------------------------------
    def glue(self) -> set[int]:
        return self._glue

    def tokenize(self, text: str) -> list[list[str]]:
        import re

        out = []
        for s in re.split(r"[.!?;\n]+", text.lower()):
            toks = TOKEN.findall(s)
            if toks:
                out.append(toks)
        return out

    def meanings(self, min_n: int = 2) -> tuple[np.ndarray, np.ndarray]:
        ids = np.array([w.id for w in self.by_id if w.n >= min_n and w.id not in self._glue], dtype=int)
        return ids, self.M[ids]

    def meaning(self, form: str) -> np.ndarray | None:
        w = self.words.get(form)
        return None if w is None else self.M[w.id]

    def meaning_of_ctx(self, ctx: np.ndarray) -> np.ndarray:
        return ctx / (np.linalg.norm(ctx) + 1e-12)

    def activity(self, w: GrownWord) -> float:
        return 1.0 / math.sqrt(1.0 + (w.n / max(self.tokens, 1)) / 0.0005)

    def context_from(self, toks: list[str], i: int, window: int = 3) -> np.ndarray:
        """One-shot meaning of position i: the habituated meanings of the known words around it
        (second order: it understands a new word through what its neighbours mean)."""
        v = np.zeros(self.D)
        for j in range(max(0, i - window), min(len(toks), i + window + 1)):
            w = self.words.get(toks[j])
            if j != i and w is not None and w.id not in self._glue:
                v += self.M[w.id] * self.activity(w) / abs(i - j)
        return v

    def neighbours(self, m: np.ndarray, k: int = 6, exclude: str | None = None) -> list[tuple[str, float]]:
        ids, M = self.meanings(min_n=5)
        s = M @ m
        top = np.argpartition(-s, min(k + 1, len(s) - 1))[: k + 1]
        out = [(self.by_id[int(ids[i])].form, float(s[i])) for i in top[np.argsort(-s[top])]]
        return [(f, v) for f, v in out if f != exclude][:k]

    def similar_forms(self, form: str, k: int = 3) -> list[tuple[str, float]]:
        if self._tri is None:
            self._tri = [trigrams(w.form) for w in self.by_id]
        t = trigrams(form)
        sc = []
        for w, u in zip(self.by_id, self._tri):
            if w.form == form or w.n < 5:
                continue
            j = len(t & u) / len(t | u)
            if j > 0.3:
                sc.append((w.form, j * (1 + 0.02 * math.log1p(w.n))))
        return [(f, round(min(1.0, j), 3)) for f, j in sorted(sc, key=lambda x: -x[1])[:k]]

    def wordlike_ref(self) -> float:
        if not hasattr(self, "_wl"):
            ws = [w.form for w in self.by_id[:400]]
            self._wl = float(np.percentile([self.letters.surprise(f, 1) for f in ws], 90))
        return self._wl

    def read_sentence(self, toks: list[str], learn: bool = False, report: bool = True) -> list[dict[str, Any]]:
        rep = []
        prev = None
        for i, tok in enumerate(toks):
            w = self.words.get(tok)
            nb = None
            if prev is not None and prev.id in self.nexts:
                nx = self.nexts[prev.id]
                tot = sum(nx.values())
                c = nx.get(w.id, 0.0) if w is not None else 0.0
                nb = -math.log2((c + 0.5) / (tot + 0.5 * (len(nx) + 1)))
            rep.append({"form": tok, "known": w is not None,
                        "letter_bits": round(self.letters.surprise(tok), 2) if report else 0.0,
                        "next_bits": None if nb is None else round(nb, 2)})  # fmt: skip
            prev = w
        if learn:  # new words: an engram whose meaning comes from this one sentence
            for i, tok in enumerate(toks):
                if tok in self.words:
                    continue
                v = self.context_from(toks, i)
                if not np.any(v):
                    continue
                w = GrownWord(len(self.by_id), tok, 1, first=" ".join(toks)[:120], born=1)
                self.by_id.append(w)
                self.words[tok] = w
                self.M = np.vstack([self.M, v / (np.linalg.norm(v) + 1e-12)])
                self._tri = None
                self._new += 1
            self.sentences += 1
        return rep
